227	
228	  static FT_Error
229	  cff_index_init( CFF_Index  idx,
230	                  FT_Stream  stream,
231	                  FT_Bool    load,
232	                  FT_Bool    cff2 )
233	  {
234	    FT_Error   error;
235	    FT_Memory  memory = stream->memory;
236	    FT_UInt    count;
237	
238	
239	    FT_ZERO( idx );
240	
241	    idx->stream = stream;
242	    idx->start  = FT_STREAM_POS();
243	
244	    if ( cff2 )
245	    {
246	      if ( FT_READ_ULONG( count ) )
247	        goto Exit;
248	      idx->hdr_size = 5;
249	    }
250	    else
251	    {
252	      if ( FT_READ_USHORT( count ) )
253	        goto Exit;
254	      idx->hdr_size = 3;
255	    }
256	
257	    if ( count > 0 )
258	    {
259	      FT_Byte   offsize;
260	      FT_ULong  size;
261	
262	
263	      /* there is at least one element; read the offset size,           */
264	      /* then access the offset table to compute the index's total size */
265	      if ( FT_READ_BYTE( offsize ) )
266	        goto Exit;
267	
268	      if ( offsize < 1 || offsize > 4 )
269	      {
270	        error = FT_THROW( Invalid_Table );
271	        goto Exit;
272	      }
273	
274	      idx->count    = count;
275	      idx->off_size = offsize;
276	      size          = (FT_ULong)( count + 1 ) * offsize;
277	
278	      idx->data_offset = idx->start + idx->hdr_size + size;
279	
280	      if ( FT_STREAM_SKIP( size - offsize ) )
281	        goto Exit;
282	
283	      size = cff_index_read_offset( idx, &error );
284	      if ( error )
285	        goto Exit;
286	
287	      if ( size == 0 )
288	      {
289	        error = FT_THROW( Invalid_Table );
290	        goto Exit;
291	      }
292	
293	      idx->data_size = --size;
294	
295	      if ( load )
296	      {
297	        /* load the data */
298	        if ( FT_FRAME_EXTRACT( size, idx->bytes ) )
299	          goto Exit;
300	      }
301	      else
302	      {
303	        /* skip the data */
304	        if ( FT_STREAM_SKIP( size ) )
305	          goto Exit;
306	      }
307	    }
308	
309	  Exit:
310	    if ( error )
311	      FT_FREE( idx->offsets );
312	
313	    return error;
314	  }
