396	  /* Allocate a table containing pointers to an index's elements. */
397	  /* The `pool' argument makes this function convert the index    */
398	  /* entries to C-style strings (this is, NULL-terminated).       */
399	  static FT_Error
400	  cff_index_get_pointers( CFF_Index   idx,
401	                          FT_Byte***  table,
402	                          FT_Byte**   pool,
403	                          FT_ULong*   pool_size )
404	  {
405	    FT_Error   error     = FT_Err_Ok;
406	    FT_Memory  memory    = idx->stream->memory;
407	
408	    FT_Byte**  t         = NULL;
409	    FT_Byte*   new_bytes = NULL;
410	    FT_ULong   new_size;
411	
412	
413	    *table = NULL;
414	
415	    if ( idx->offsets == NULL )
416	    {
417	      error = cff_index_load_offsets( idx );
418	      if ( error )
419	        goto Exit;
420	    }
421	
422	    new_size = idx->data_size + idx->count;
423	
424	    if ( idx->count > 0                                &&
425	         !FT_NEW_ARRAY( t, idx->count + 1 )            &&
426	         ( !pool || !FT_ALLOC( new_bytes, new_size ) ) )
427	    {
428	      FT_ULong  n, cur_offset;
429	      FT_ULong  extra = 0;
430	      FT_Byte*  org_bytes = idx->bytes;
431	
432	
433	      /* at this point, `idx->offsets' can't be NULL */
434	      cur_offset = idx->offsets[0] - 1;
435	
436	      /* sanity check */
437	      if ( cur_offset != 0 )
438	      {
439	        FT_TRACE0(( "cff_index_get_pointers:"
440	                    " invalid first offset value %d set to zero\n",
441	                    cur_offset ));
442	        cur_offset = 0;
443	      }
444	
445	      if ( !pool )
446	        t[0] = org_bytes + cur_offset;
447	      else
448	        t[0] = new_bytes + cur_offset;
449	
450	      for ( n = 1; n <= idx->count; n++ )
451	      {
452	        FT_ULong  next_offset = idx->offsets[n] - 1;
453	
454	
455	        /* two sanity checks for invalid offset tables */
456	        if ( next_offset < cur_offset )
457	          next_offset = cur_offset;
458	        else if ( next_offset > idx->data_size )
459	          next_offset = idx->data_size;
460	
461	        if ( !pool )
462	          t[n] = org_bytes + next_offset;
463	        else
464	        {
465	          t[n] = new_bytes + next_offset + extra;
466	
467	          if ( next_offset != cur_offset )
468	          {
469	            FT_MEM_COPY( t[n - 1], org_bytes + cur_offset, t[n] - t[n - 1] );
470	            t[n][0] = '\0';
471	            t[n]   += 1;
472	            extra++;
473	          }
474	        }
475	
476	        cur_offset = next_offset;
477	      }
478	      *table = t;
479	
480	      if ( pool )
481	        *pool = new_bytes;
482	      if ( pool_size )
483	        *pool_size = new_size;
484	    }
485	
486	  Exit:
487	    return error;
488	  }
