491	  FT_LOCAL_DEF( FT_Error )
492	  cff_index_access_element( CFF_Index  idx,
493	                            FT_UInt    element,
494	                            FT_Byte**  pbytes,
495	                            FT_ULong*  pbyte_len )
496	  {
497	    FT_Error  error = FT_Err_Ok;
498	
499	
500	    if ( idx && idx->count > element )
501	    {
502	      /* compute start and end offsets */
503	      FT_Stream  stream = idx->stream;
504	      FT_ULong   off1, off2 = 0;
505	
506	
507	      /* load offsets from file or the offset table */
508	      if ( !idx->offsets )
509	      {
510	        FT_ULong  pos = element * idx->off_size;
511	
512	
513	        if ( FT_STREAM_SEEK( idx->start + idx->hdr_size + pos ) )
514	          goto Exit;
515	
516	        off1 = cff_index_read_offset( idx, &error );
517	        if ( error )
518	          goto Exit;
519	
520	        if ( off1 != 0 )
521	        {
522	          do
523	          {
524	            element++;
525	            off2 = cff_index_read_offset( idx, &error );
526	
527	          } while ( off2 == 0 && element < idx->count );
528	        }
529	      }
530	      else   /* use offsets table */
531	      {
532	        off1 = idx->offsets[element];
533	        if ( off1 )
534	        {
535	          do
536	          {
537	            element++;
538	            off2 = idx->offsets[element];
539	
540	          } while ( off2 == 0 && element < idx->count );
541	        }
542	      }
543	
544	      /* XXX: should check off2 does not exceed the end of this entry; */
545	      /*      at present, only truncate off2 at the end of this stream */
546	      if ( off2 > stream->size + 1                    ||
547	           idx->data_offset > stream->size - off2 + 1 )
548	      {
549	        FT_ERROR(( "cff_index_access_element:"
550	                   " offset to next entry (%d)"
551	                   " exceeds the end of stream (%d)\n",
552	                   off2, stream->size - idx->data_offset + 1 ));
553	        off2 = stream->size - idx->data_offset + 1;
554	      }
555	
556	      /* access element */
557	      if ( off1 && off2 > off1 )
558	      {
559	        *pbyte_len = off2 - off1;
560	
561	        if ( idx->bytes )
562	        {
563	          /* this index was completely loaded in memory, that's easy */
564	          *pbytes = idx->bytes + off1 - 1;
565	        }
566	        else
567	        {
568	          /* this index is still on disk/file, access it through a frame */
569	          if ( FT_STREAM_SEEK( idx->data_offset + off1 - 1 ) ||
570	               FT_FRAME_EXTRACT( off2 - off1, *pbytes )      )
571	            goto Exit;
572	        }
573	      }
574	      else
575	      {
576	        /* empty index element */
577	        *pbytes    = 0;
578	        *pbyte_len = 0;
579	      }
580	    }
581	    else
582	      error = FT_THROW( Invalid_Argument );
583	
584	  Exit:
585	    return error;
586	  }
