589	  FT_LOCAL_DEF( void )
590	  cff_index_forget_element( CFF_Index  idx,
591	                            FT_Byte**  pbytes )
592	  {
593	    if ( idx->bytes == 0 )
594	    {
595	      FT_Stream  stream = idx->stream;
596	
597	
598	      FT_FRAME_RELEASE( *pbytes );
599	    }
600	  }
