604	  FT_LOCAL_DEF( FT_String* )
605	  cff_index_get_name( CFF_Font  font,
606	                      FT_UInt   element )
607	  {
608	    CFF_Index   idx = &font->name_index;
609	    FT_Memory   memory;
610	    FT_Byte*    bytes;
611	    FT_ULong    byte_len;
612	    FT_Error    error;
613	    FT_String*  name = 0;
614	
615	
616	    if ( !idx->stream )  /* CFF2 does not include a name index */
617	      goto Exit;
618	
619	    memory = idx->stream->memory;
620	
621	    error = cff_index_access_element( idx, element, &bytes, &byte_len );
622	    if ( error )
623	      goto Exit;
624	
625	    if ( !FT_ALLOC( name, byte_len + 1 ) )
626	    {
627	      if ( byte_len )
628	        FT_MEM_COPY( name, bytes, byte_len );
629	      name[byte_len] = 0;
630	    }
631	    cff_index_forget_element( idx, &bytes );
632	
633	  Exit:
634	    return name;
635	  }
