649	  FT_LOCAL_DEF( FT_String* )
650	  cff_index_get_sid_string( CFF_Font  font,
651	                            FT_UInt   sid )
652	  {
653	    /* value 0xFFFFU indicates a missing dictionary entry */
654	    if ( sid == 0xFFFFU )
655	      return NULL;
656	
657	    /* if it is not a standard string, return it */
658	    if ( sid > 390 )
659	      return cff_index_get_string( font, sid - 391 );
660	
661	    /* CID-keyed CFF fonts don't have glyph names */
662	    if ( !font->psnames )
663	      return NULL;
664	
665	    /* this is a standard string */
666	    return (FT_String *)font->psnames->adobe_std_strings( sid );
667	  }
