679	  static void
680	  CFF_Done_FD_Select( CFF_FDSelect  fdselect,
681	                      FT_Stream     stream )
682	  {
683	    if ( fdselect->data )
684	      FT_FRAME_RELEASE( fdselect->data );
685	
686	    fdselect->data_size   = 0;
687	    fdselect->format      = 0;
688	    fdselect->range_count = 0;
689	  }
690	
691	
692	  static FT_Error
693	  CFF_Load_FD_Select( CFF_FDSelect  fdselect,
694	                      FT_UInt       num_glyphs,
695	                      FT_Stream     stream,
696	                      FT_ULong      offset )
697	  {
698	    FT_Error  error;
699	    FT_Byte   format;
700	    FT_UInt   num_ranges;
701	
702	
703	    /* read format */
704	    if ( FT_STREAM_SEEK( offset ) || FT_READ_BYTE( format ) )
705	      goto Exit;
706	
707	    fdselect->format      = format;
708	    fdselect->cache_count = 0;   /* clear cache */
709	
710	    switch ( format )
711	    {
712	    case 0:     /* format 0, that's simple */
713	      fdselect->data_size = num_glyphs;
714	      goto Load_Data;
715	
716	    case 3:     /* format 3, a tad more complex */
717	      if ( FT_READ_USHORT( num_ranges ) )
718	        goto Exit;
719	
720	      if ( !num_ranges )
721	      {
722	        FT_TRACE0(( "CFF_Load_FD_Select: empty FDSelect array\n" ));
723	        error = FT_THROW( Invalid_File_Format );
724	        goto Exit;
725	      }
726	
727	      fdselect->data_size = num_ranges * 3 + 2;
728	
729	    Load_Data:
730	      if ( FT_FRAME_EXTRACT( fdselect->data_size, fdselect->data ) )
731	        goto Exit;
732	      break;
733	
734	    default:    /* hmm... that's wrong */
735	      error = FT_THROW( Invalid_File_Format );
736	    }
737	
738	  Exit:
739	    return error;
740	  }
741	
742	
743	  FT_LOCAL_DEF( FT_Byte )
744	  cff_fd_select_get( CFF_FDSelect  fdselect,
745	                     FT_UInt       glyph_index )
746	  {
747	    FT_Byte  fd = 0;
748	
749	    /* if there is no FDSelect, return zero               */
750	    /* Note: CFF2 with just one Font Dict has no FDSelect */
751	    if ( fdselect->data == NULL )
752	      goto Exit;
753	
754	    switch ( fdselect->format )
755	    {
756	    case 0:
757	      fd = fdselect->data[glyph_index];
758	      break;
759	
760	    case 3:
761	      /* first, compare to the cache */
762	      if ( (FT_UInt)( glyph_index - fdselect->cache_first ) <
763	                        fdselect->cache_count )
764	      {
765	        fd = fdselect->cache_fd;
766	        break;
767	      }
768	
769	      /* then, look up the ranges array */
770	      {
771	        FT_Byte*  p       = fdselect->data;
772	        FT_Byte*  p_limit = p + fdselect->data_size;
773	        FT_Byte   fd2;
774	        FT_UInt   first, limit;
775	
776	
777	        first = FT_NEXT_USHORT( p );
778	        do
779	        {
780	          if ( glyph_index < first )
781	            break;
782	
783	          fd2   = *p++;
784	          limit = FT_NEXT_USHORT( p );
785	
786	          if ( glyph_index < limit )
787	          {
788	            fd = fd2;
789	
790	            /* update cache */
791	            fdselect->cache_first = first;
792	            fdselect->cache_count = limit - first;
793	            fdselect->cache_fd    = fd2;
794	            break;
795	          }
796	          first = limit;
797	
798	        } while ( p < p_limit );
799	      }
800	      break;
801	
802	    default:
803	      ;
804	    }
805	
806	  Exit:
807	    return fd;
808	  }
