880	  cff_charset_done( CFF_Charset  charset,
881	                    FT_Stream    stream )
882	  {
883	    FT_Memory  memory = stream->memory;
884	
885	
886	    cff_charset_free_cids( charset, memory );
887	
888	    FT_FREE( charset->sids );
889	    charset->format = 0;
890	    charset->offset = 0;
891	  }
