317	  static void
318	  cff_index_done( CFF_Index  idx )
319	  {
320	    if ( idx->stream )
321	    {
322	      FT_Stream  stream = idx->stream;
323	      FT_Memory  memory = stream->memory;
324	
325	
326	      if ( idx->bytes )
327	        FT_FRAME_RELEASE( idx->bytes );
328	
329	      FT_FREE( idx->offsets );
330	      FT_ZERO( idx );
331	    }
332	  }
