639	  FT_LOCAL_DEF( FT_String* )
640	  cff_index_get_string( CFF_Font  font,
641	                        FT_UInt   element )
642	  {
643	    return ( element < font->num_strings )
644	             ? (FT_String*)font->strings[element]
645	             : NULL;
