893	
894	  static FT_Error
895	  cff_charset_load( CFF_Charset  charset,
896	                    FT_UInt      num_glyphs,
897	                    FT_Stream    stream,
898	                    FT_ULong     base_offset,
899	                    FT_ULong     offset,
900	                    FT_Bool      invert )
901	  {
902	    FT_Memory  memory = stream->memory;
903	    FT_Error   error  = FT_Err_Ok;
904	    FT_UShort  glyph_sid;
905	
906	
907	    /* If the offset is greater than 2, we have to parse the charset */
908	    /* table.                                                        */
909	    if ( offset > 2 )
910	    {
911	      FT_UInt  j;
912	
913	
914	      charset->offset = base_offset + offset;
915	
916	      /* Get the format of the table. */
917	      if ( FT_STREAM_SEEK( charset->offset ) ||
918	           FT_READ_BYTE( charset->format )   )
919	        goto Exit;
920	
921	      /* Allocate memory for sids. */
922	      if ( FT_NEW_ARRAY( charset->sids, num_glyphs ) )
923	        goto Exit;
924	
925	      /* assign the .notdef glyph */
926	      charset->sids[0] = 0;
927	
928	      switch ( charset->format )
929	      {
930	      case 0:
931	        if ( num_glyphs > 0 )
932	        {
933	          if ( FT_FRAME_ENTER( ( num_glyphs - 1 ) * 2 ) )
934	            goto Exit;
935	
936	          for ( j = 1; j < num_glyphs; j++ )
937	            charset->sids[j] = FT_GET_USHORT();
938	
939	          FT_FRAME_EXIT();
940	        }
941	        break;
942	
943	      case 1:
944	      case 2:
945	        {
946	          FT_UInt  nleft;
947	          FT_UInt  i;
948	
949	
950	          j = 1;
951	
952	          while ( j < num_glyphs )
953	          {
954	            /* Read the first glyph sid of the range. */
955	            if ( FT_READ_USHORT( glyph_sid ) )
956	              goto Exit;
957	
958	            /* Read the number of glyphs in the range.  */
959	            if ( charset->format == 2 )
960	            {
961	              if ( FT_READ_USHORT( nleft ) )
962	                goto Exit;
963	            }
964	            else
965	            {
966	              if ( FT_READ_BYTE( nleft ) )
967	                goto Exit;
968	            }
969	
970	            /* try to rescue some of the SIDs if `nleft' is too large */
971	            if ( glyph_sid > 0xFFFFL - nleft )
972	            {
973	              FT_ERROR(( "cff_charset_load: invalid SID range trimmed"
974	                         " nleft=%d -> %d\n", nleft, 0xFFFFL - glyph_sid ));
975	              nleft = ( FT_UInt )( 0xFFFFL - glyph_sid );
976	            }
977	
978	            /* Fill in the range of sids -- `nleft + 1' glyphs. */
979	            for ( i = 0; j < num_glyphs && i <= nleft; i++, j++, glyph_sid++ )
980	              charset->sids[j] = glyph_sid;
981	          }
982	        }
983	        break;
984	
985	      default:
986	        FT_ERROR(( "cff_charset_load: invalid table format\n" ));
987	        error = FT_THROW( Invalid_File_Format );
988	        goto Exit;
989	      }
990	    }
991	    else
992	    {
993	      /* Parse default tables corresponding to offset == 0, 1, or 2.  */
994	      /* CFF specification intimates the following:                   */
995	      /*                                                              */
996	      /* In order to use a predefined charset, the following must be  */
997	      /* true: The charset constructed for the glyphs in the font's   */
998	      /* charstrings dictionary must match the predefined charset in  */
999	      /* the first num_glyphs.                                        */
1000	
1001	      charset->offset = offset;  /* record charset type */
1002	
1003	      switch ( (FT_UInt)offset )
1004	      {
1005	      case 0:
1006	        if ( num_glyphs > 229 )
1007	        {
1008	          FT_ERROR(( "cff_charset_load: implicit charset larger than\n"
1009	                     "predefined charset (Adobe ISO-Latin)\n" ));
1010	          error = FT_THROW( Invalid_File_Format );
1011	          goto Exit;
1012	        }
1013	
1014	        /* Allocate memory for sids. */
1015	        if ( FT_NEW_ARRAY( charset->sids, num_glyphs ) )
1016	          goto Exit;
1017	
1018	        /* Copy the predefined charset into the allocated memory. */
1019	        FT_ARRAY_COPY( charset->sids, cff_isoadobe_charset, num_glyphs );
1020	
1021	        break;
1022	
1023	      case 1:
1024	        if ( num_glyphs > 166 )
1025	        {
1026	          FT_ERROR(( "cff_charset_load: implicit charset larger than\n"
1027	                     "predefined charset (Adobe Expert)\n" ));
1028	          error = FT_THROW( Invalid_File_Format );
1029	          goto Exit;
1030	        }
1031	
1032	        /* Allocate memory for sids. */
1033	        if ( FT_NEW_ARRAY( charset->sids, num_glyphs ) )
1034	          goto Exit;
1035	
1036	        /* Copy the predefined charset into the allocated memory.     */
1037	        FT_ARRAY_COPY( charset->sids, cff_expert_charset, num_glyphs );
1038	
1039	        break;
1040	
1041	      case 2:
1042	        if ( num_glyphs > 87 )
1043	        {
1044	          FT_ERROR(( "cff_charset_load: implicit charset larger than\n"
1045	                     "predefined charset (Adobe Expert Subset)\n" ));
1046	          error = FT_THROW( Invalid_File_Format );
1047	          goto Exit;
1048	        }
1049	
1050	        /* Allocate memory for sids. */
1051	        if ( FT_NEW_ARRAY( charset->sids, num_glyphs ) )
1052	          goto Exit;
1053	
1054	        /* Copy the predefined charset into the allocated memory.     */
1055	        FT_ARRAY_COPY( charset->sids, cff_expertsubset_charset, num_glyphs );
1056	
1057	        break;
1058	
1059	      default:
1060	        error = FT_THROW( Invalid_File_Format );
1061	        goto Exit;
1062	      }
1063	    }
1064	
1065	    /* we have to invert the `sids' array for subsetted CID-keyed fonts */
1066	    if ( invert )
1067	      error = cff_charset_compute_cids( charset, num_glyphs, memory );
1068	
1069	  Exit:
1070	    /* Clean up if there was an error. */
1071	    if ( error )
1072	    {
1073	      FT_FREE( charset->sids );
1074	      FT_FREE( charset->cids );
1075	      charset->format = 0;
1076	      charset->offset = 0;
1077	      charset->sids   = 0;
1078	    }
1079	
1080	    return error;
1081	  }
1082	
1083	
1084	  static void
1085	  cff_vstore_done( CFF_VStoreRec*  vstore,
1086	                   FT_Memory       memory )
1087	  {
1088	    FT_UInt  i;
1089	
1090	
1091	    /* free regionList and axisLists */
1092	    if ( vstore->varRegionList )
1093	    {
1094	      for ( i = 0; i < vstore->regionCount; i++ )
1095	        FT_FREE( vstore->varRegionList[i].axisList );
1096	    }
1097	    FT_FREE( vstore->varRegionList );
1098	
1099	    /* free varData and indices */
1100	    if ( vstore->varData )
1101	    {
1102	      for ( i = 0; i < vstore->dataCount; i++ )
1103	        FT_FREE( vstore->varData[i].regionIndices );
1104	    }
1105	    FT_FREE( vstore->varData );
1106	  }
1107	
1108	
1109	  /* convert 2.14 to Fixed */
1110	  #define FT_fdot14ToFixed( x )  ( ( (FT_Fixed)( (FT_Int16)(x) ) ) << 2 )
1111	
1112	
1113	  static FT_Error
1114	  cff_vstore_load( CFF_VStoreRec*  vstore,
1115	                   FT_Stream       stream,
1116	                   FT_ULong        base_offset,
1117	                   FT_ULong        offset )
1118	  {
1119	    FT_Memory  memory = stream->memory;
1120	    FT_Error   error  = FT_ERR( Invalid_File_Format );
1121	
1122	    FT_ULong*  dataOffsetArray = NULL;
1123	    FT_UInt    i, j;
1124	
1125	
1126	    /* no offset means no vstore to parse */
1127	    if ( offset )
1128	    {
1129	      FT_UInt   vsSize;     /* currently unused */
1130	      FT_UInt   vsOffset;
1131	      FT_UInt   format;
1132	      FT_ULong  regionListOffset;
1133	
1134	
1135	      /* we need to parse the table to determine its size */
1136	      if ( FT_STREAM_SEEK( base_offset + offset ) ||
1137	           FT_READ_USHORT( vsSize )               )
1138	        goto Exit;
1139	
1140	      /* actual variation store begins after the length */
1141	      vsOffset = FT_STREAM_POS();
1142	
1143	      /* check the header */
1144	      if ( FT_READ_USHORT( format ) )
1145	        goto Exit;
1146	      if ( format != 1 )
1147	      {
1148	        error = FT_THROW( Invalid_File_Format );
1149	        goto Exit;
1150	      }
1151	
1152	      /* read top level fields */
1153	      if ( FT_READ_ULONG( regionListOffset )   ||
1154	           FT_READ_USHORT( vstore->dataCount ) )
1155	        goto Exit;
1156	
1157	      /* make temporary copy of item variation data offsets; */
1158	      /* we'll parse region list first, then come back       */
1159	      if ( FT_NEW_ARRAY( dataOffsetArray, vstore->dataCount ) )
1160	        goto Exit;
1161	
1162	      for ( i = 0; i < vstore->dataCount; i++ )
1163	      {
1164	        if ( FT_READ_ULONG( dataOffsetArray[i] ) )
1165	          goto Exit;
1166	      }
1167	
1168	      /* parse regionList and axisLists */
1169	      if ( FT_STREAM_SEEK( vsOffset + regionListOffset ) ||
1170	           FT_READ_USHORT( vstore->axisCount )           ||
1171	           FT_READ_USHORT( vstore->regionCount )         )
1172	        goto Exit;
1173	
1174	      if ( FT_NEW_ARRAY( vstore->varRegionList, vstore->regionCount ) )
1175	        goto Exit;
1176	
1177	      for ( i = 0; i < vstore->regionCount; i++ )
1178	      {
1179	        CFF_VarRegion*  region = &vstore->varRegionList[i];
1180	
1181	
1182	        if ( FT_NEW_ARRAY( region->axisList, vstore->axisCount ) )
1183	          goto Exit;
1184	
1185	        for ( j = 0; j < vstore->axisCount; j++ )
1186	        {
1187	          CFF_AxisCoords*  axis = &region->axisList[j];
1188	
1189	          FT_Int16  start14, peak14, end14;
1190	
1191	
1192	          if ( FT_READ_SHORT( start14 ) ||
1193	               FT_READ_SHORT( peak14 )  ||
1194	               FT_READ_SHORT( end14 )   )
1195	            goto Exit;
1196	
1197	          axis->startCoord = FT_fdot14ToFixed( start14 );
1198	          axis->peakCoord  = FT_fdot14ToFixed( peak14 );
1199	          axis->endCoord   = FT_fdot14ToFixed( end14 );
1200	        }
1201	      }
1202	
1203	      /* use dataOffsetArray now to parse varData items */
1204	      if ( FT_NEW_ARRAY( vstore->varData, vstore->dataCount ) )
1205	        goto Exit;
1206	
1207	      for ( i = 0; i < vstore->dataCount; i++ )
1208	      {
1209	        CFF_VarData*  data = &vstore->varData[i];
1210	
1211	
1212	        if ( FT_STREAM_SEEK( vsOffset + dataOffsetArray[i] ) )
1213	          goto Exit;
1214	
1215	        /* ignore `itemCount' and `shortDeltaCount' */
1216	        /* because CFF2 has no delta sets           */
1217	        if ( FT_STREAM_SKIP( 4 ) )
1218	          goto Exit;
1219	
1220	        /* Note: just record values; consistency is checked later    */
1221	        /*       by cff_blend_build_vector when it consumes `vstore' */
1222	
1223	        if ( FT_READ_USHORT( data->regionIdxCount ) )
1224	          goto Exit;
1225	
1226	        if ( FT_NEW_ARRAY( data->regionIndices, data->regionIdxCount ) )
1227	          goto Exit;
1228	
1229	        for ( j = 0; j < data->regionIdxCount; j++ )
1230	        {
1231	          if ( FT_READ_USHORT( data->regionIndices[j] ) )
1232	            goto Exit;
1233	        }
1234	      }
1235	    }
1236	
1237	    error = FT_Err_Ok;
1238	
1239	  Exit:
1240	    FT_FREE( dataOffsetArray );
1241	    if ( error )
1242	      cff_vstore_done( vstore, memory );
1243	
1244	    return error;
1245	  }
1246	
1247	
1248	  /* Clear blend stack (after blend values are consumed). */
1249	  /*                                                      */
1250	  /* TODO: Should do this in cff_run_parse, but subFont   */
1251	  /*       ref is not available there.                    */
1252	  /*                                                      */
1253	  /* Allocation is not changed when stack is cleared.     */
1254	  FT_LOCAL_DEF( void )
1255	  cff_blend_clear( CFF_SubFont  subFont )
1256	  {
1257	    subFont->blend_top  = subFont->blend_stack;
1258	    subFont->blend_used = 0;
1259	  }
1260	
1261	
1262	  /* Blend numOperands on the stack,                       */
1263	  /* store results into the first numBlends values,        */
1264	  /* then pop remaining arguments.                         */
1265	  /*                                                       */
1266	  /* This is comparable to `cf2_doBlend' but               */
1267	  /* the cffparse stack is different and can't be written. */
1268	  /* Blended values are written to a different buffer,     */
1269	  /* using reserved operator 255.                          */
1270	  /*                                                       */
1271	  /* Blend calculation is done in 16.16 fixed point.       */
1272	  FT_LOCAL_DEF( FT_Error )
1273	  cff_blend_doBlend( CFF_SubFont  subFont,
1274	                     CFF_Parser   parser,
1275	                     FT_UInt      numBlends )
1276	  {
1277	    FT_UInt  delta;
1278	    FT_UInt  base;
1279	    FT_UInt  i, j;
1280	    FT_UInt  size;
1281	
1282	    CFF_Blend  blend = &subFont->blend;
1283	
1284	    FT_Memory  memory = subFont->blend.font->memory; /* for FT_REALLOC */
1285	    FT_Error   error  = FT_Err_Ok;                   /* for FT_REALLOC */
1286	
1287	    /* compute expected number of operands for this blend */
1288	    FT_UInt  numOperands = (FT_UInt)( numBlends * blend->lenBV );
1289	    FT_UInt  count       = (FT_UInt)( parser->top - 1 - parser->stack );
1290	
1291	
1292	    if ( numOperands > count )
1293	    {
1294	      FT_TRACE4(( " cff_blend_doBlend: Stack underflow %d args\n", count ));
1295	
1296	      error = FT_THROW( Stack_Underflow );
1297	      goto Exit;
1298	    }
1299	
1300	    /* check whether we have room for `numBlends' values at `blend_top' */
1301	    size = 5 * numBlends;           /* add 5 bytes per entry    */
1302	    if ( subFont->blend_used + size > subFont->blend_alloc )
1303	    {
1304	      /* increase or allocate `blend_stack' and reset `blend_top'; */
1305	      /* prepare to append `numBlends' values to the buffer        */
1306	      if ( FT_REALLOC( subFont->blend_stack,
1307	                       subFont->blend_alloc,
1308	                       subFont->blend_alloc + size ) )
1309	        goto Exit;
1310	
1311	      subFont->blend_top    = subFont->blend_stack + subFont->blend_used;
1312	      subFont->blend_alloc += size;
1313	    }
1314	    subFont->blend_used += size;
1315	
1316	    base  = count - numOperands;     /* index of first blend arg */
1317	    delta = base + numBlends;        /* index of first delta arg */
1318	
1319	    for ( i = 0; i < numBlends; i++ )
1320	    {
1321	      const FT_Int32*  weight = &blend->BV[1];
1322	      FT_Int32         sum;
1323	
1324	
1325	      /* convert inputs to 16.16 fixed point */
1326	      sum = cff_parse_num( parser, &parser->stack[i + base] ) << 16;
1327	
1328	      for ( j = 1; j < blend->lenBV; j++ )
1329	        sum += FT_MulFix( *weight++,
1330	                          cff_parse_num( parser,
1331	                                         &parser->stack[delta++] ) << 16 );
1332	
1333	      /* point parser stack to new value on blend_stack */
1334	      parser->stack[i + base] = subFont->blend_top;
1335	
1336	      /* Push blended result as Type 2 5-byte fixed point number (except   */
1337	      /* that host byte order is used).  This will not conflict with       */
1338	      /* actual DICTs because 255 is a reserved opcode in both CFF and     */
1339	      /* CFF2 DICTs.  See `cff_parse_num' for decode of this, which rounds */
1340	      /* to an integer.                                                    */
1341	      *subFont->blend_top++             = 255;
1342	      *((FT_UInt32*)subFont->blend_top) = (FT_UInt32)sum; /* write 4 bytes */
1343	      subFont->blend_top               += 4;
1344	    }
1345	
1346	    /* leave only numBlends results on parser stack */
1347	    parser->top = &parser->stack[base + numBlends];
1348	
1349	  Exit:
1350	    return error;
1351	  }
1352	
1353	
1354	  /* Compute a blend vector from variation store index and normalized  */
1355	  /* vector based on pseudo-code in OpenType Font Variations Overview. */
1356	  /*                                                                   */
1357	  /* Note: lenNDV == 0 produces a default blend vector, (1,0,0,...).   */
1358	  FT_LOCAL_DEF( FT_Error )
1359	  cff_blend_build_vector( CFF_Blend  blend,
1360	                          FT_UInt    vsindex,
1361	                          FT_UInt    lenNDV,
1362	                          FT_Fixed*  NDV )
1363	  {
1364	    FT_Error   error  = FT_Err_Ok;            /* for FT_REALLOC */
1365	    FT_Memory  memory = blend->font->memory;  /* for FT_REALLOC */
1366	
1367	    FT_UInt       len;
1368	    CFF_VStore    vs;
1369	    CFF_VarData*  varData;
1370	    FT_UInt       master;
1371	
1372	
1373	    FT_ASSERT( lenNDV == 0 || NDV );
1374	
1375	    blend->builtBV = FALSE;
1376	
1377	    vs = &blend->font->vstore;
1378	
1379	    /* VStore and fvar must be consistent */
1380	    if ( lenNDV != 0 && lenNDV != vs->axisCount )
1381	    {
1382	      FT_TRACE4(( " cff_blend_build_vector: Axis count mismatch\n" ));
1383	      error = FT_THROW( Invalid_File_Format );
1384	      goto Exit;
1385	    }
1386	
1387	    if ( vsindex >= vs->dataCount )
1388	    {
1389	      FT_TRACE4(( " cff_blend_build_vector: vsindex out of range\n" ));
1390	      error = FT_THROW( Invalid_File_Format );
1391	      goto Exit;
1392	    }
1393	
1394	    /* select the item variation data structure */
1395	    varData = &vs->varData[vsindex];
1396	
1397	    /* prepare buffer for the blend vector */
1398	    len = varData->regionIdxCount + 1;    /* add 1 for default component */
1399	    if ( FT_REALLOC( blend->BV,
1400	                     blend->lenBV * sizeof( *blend->BV ),
1401	                     len * sizeof( *blend->BV ) ) )
1402	      goto Exit;
1403	
1404	    blend->lenBV = len;
1405	
1406	    /* outer loop steps through master designs to be blended */
1407	    for ( master = 0; master < len; master++ )
1408	    {
1409	      FT_UInt         j;
1410	      FT_UInt         idx;
1411	      CFF_VarRegion*  varRegion;
1412	
1413	
1414	      /* default factor is always one */
1415	      if ( master == 0 )
1416	      {
1417	        blend->BV[master] = FT_FIXED_ONE;
1418	        FT_TRACE4(( "   build blend vector len %d\n"
1419	                    "   [ %f ",
1420	                    len,
1421	                    blend->BV[master] / 65536.0 ));
1422	        continue;
1423	      }
1424	
1425	      /* VStore array does not include default master, so subtract one */
1426	      idx       = varData->regionIndices[master - 1];
1427	      varRegion = &vs->varRegionList[idx];
1428	
1429	      if ( idx >= vs->regionCount )
1430	      {
1431	        FT_TRACE4(( " cff_blend_build_vector:"
1432	                    " region index out of range\n" ));
1433	        error = FT_THROW( Invalid_File_Format );
1434	        goto Exit;
1435	      }
1436	
1437	      /* Note: `lenNDV' could be zero.                              */
1438	      /*       In that case, build default blend vector (1,0,0...). */
1439	      /*       In the normal case, initialize each component to 1   */
1440	      /*       before inner loop.                                   */
1441	      if ( lenNDV != 0 )
1442	        blend->BV[master] = FT_FIXED_ONE; /* default */
1443	
1444	      /* inner loop steps through axes in this region */
1445	      for ( j = 0; j < lenNDV; j++ )
1446	      {
1447	        CFF_AxisCoords*  axis = &varRegion->axisList[j];
1448	        FT_Fixed         axisScalar;
1449	
1450	
1451	        /* compute the scalar contribution of this axis; */
1452	        /* ignore invalid ranges                         */
1453	        if ( axis->startCoord > axis->peakCoord ||
1454	             axis->peakCoord > axis->endCoord   )
1455	          axisScalar = FT_FIXED_ONE;
1456	
1457	        else if ( axis->startCoord < 0 &&
1458	                  axis->endCoord > 0   &&
1459	                  axis->peakCoord != 0 )
1460	          axisScalar = FT_FIXED_ONE;
1461	
1462	        /* peak of 0 means ignore this axis */
1463	        else if ( axis->peakCoord == 0 )
1464	          axisScalar = FT_FIXED_ONE;
1465	
1466	        /* ignore this region if coords are out of range */
1467	        else if ( NDV[j] < axis->startCoord ||
1468	                  NDV[j] > axis->endCoord   )
1469	          axisScalar = 0;
1470	
1471	        /* calculate a proportional factor */
1472	        else
1473	        {
1474	          if ( NDV[j] == axis->peakCoord )
1475	            axisScalar = FT_FIXED_ONE;
1476	          else if ( NDV[j] < axis->peakCoord )
1477	            axisScalar = FT_DivFix( NDV[j] - axis->startCoord,
1478	                                    axis->peakCoord - axis->startCoord );
1479	          else
1480	            axisScalar = FT_DivFix( axis->endCoord - NDV[j],
1481	                                    axis->endCoord - axis->peakCoord );
1482	        }
1483	
1484	        /* take product of all the axis scalars */
1485	        blend->BV[master] = FT_MulFix( blend->BV[master], axisScalar );
1486	      }
1487	
1488	      FT_TRACE4(( ", %f ",
1489	                  blend->BV[master] / 65536.0 ));
1490	    }
1491	
1492	    FT_TRACE4(( "]\n" ));
1493	
1494	    /* record the parameters used to build the blend vector */
1495	    blend->lastVsindex = vsindex;
1496	
1497	    if ( lenNDV != 0 )
1498	    {
1499	      /* user has set a normalized vector */
1500	      if ( FT_REALLOC( blend->lastNDV,
1501	                       blend->lenNDV * sizeof ( *NDV ),
1502	                       lenNDV * sizeof ( *NDV ) ) )
1503	      {
1504	        error = FT_THROW( Out_Of_Memory );
1505	        goto Exit;
1506	      }
1507	
1508	      blend->lenNDV = lenNDV;
1509	      FT_MEM_COPY( blend->lastNDV,
1510	                   NDV,
1511	                   lenNDV * sizeof ( *NDV ) );
1512	    }
1513	
1514	    blend->builtBV = TRUE;
1515	
1516	  Exit:
1517	    return error;
1518	  }
1519	
1520	
1521	  /* `lenNDV' is zero for default vector;           */
1522	  /* return TRUE if blend vector needs to be built. */
1523	  FT_LOCAL_DEF( FT_Bool )
1524	  cff_blend_check_vector( CFF_Blend  blend,
1525	                          FT_UInt    vsindex,
1526	                          FT_UInt    lenNDV,
1527	                          FT_Fixed*  NDV )
1528	  {
1529	    if ( !blend->builtBV                             ||
1530	         blend->lastVsindex != vsindex               ||
1531	         blend->lenNDV != lenNDV                     ||
1532	         ( lenNDV                                  &&
1533	           memcmp( NDV,
1534	                   blend->lastNDV,
1535	                   lenNDV * sizeof ( *NDV ) ) != 0 ) )
1536	    {
1537	      /* need to build blend vector */
1538	      return TRUE;
1539	    }
1540	
1541	    return FALSE;
1542	  }
