1570	
1571	  static void
1572	  cff_encoding_done( CFF_Encoding  encoding )
1573	  {
1574	    encoding->format = 0;
1575	    encoding->offset = 0;
1576	    encoding->count  = 0;
1577	  }
1578	
1579	
1580	  static FT_Error
1581	  cff_encoding_load( CFF_Encoding  encoding,
1582	                     CFF_Charset   charset,
1583	                     FT_UInt       num_glyphs,
1584	                     FT_Stream     stream,
1585	                     FT_ULong      base_offset,
1586	                     FT_ULong      offset )
1587	  {
1588	    FT_Error   error = FT_Err_Ok;
1589	    FT_UInt    count;
1590	    FT_UInt    j;
1591	    FT_UShort  glyph_sid;
1592	    FT_UInt    glyph_code;
1593	
1594	
1595	    /* Check for charset->sids.  If we do not have this, we fail. */
1596	    if ( !charset->sids )
1597	    {
1598	      error = FT_THROW( Invalid_File_Format );
1599	      goto Exit;
1600	    }
1601	
1602	    /* Zero out the code to gid/sid mappings. */
1603	    for ( j = 0; j < 256; j++ )
1604	    {
1605	      encoding->sids [j] = 0;
1606	      encoding->codes[j] = 0;
1607	    }
1608	
1609	    /* Note: The encoding table in a CFF font is indexed by glyph index;  */
1610	    /* the first encoded glyph index is 1.  Hence, we read the character  */
1611	    /* code (`glyph_code') at index j and make the assignment:            */
1612	    /*                                                                    */
1613	    /*    encoding->codes[glyph_code] = j + 1                             */
1614	    /*                                                                    */
1615	    /* We also make the assignment:                                       */
1616	    /*                                                                    */
1617	    /*    encoding->sids[glyph_code] = charset->sids[j + 1]               */
1618	    /*                                                                    */
1619	    /* This gives us both a code to GID and a code to SID mapping.        */
1620	
1621	    if ( offset > 1 )
1622	    {
1623	      encoding->offset = base_offset + offset;
1624	
1625	      /* we need to parse the table to determine its size */
1626	      if ( FT_STREAM_SEEK( encoding->offset ) ||
1627	           FT_READ_BYTE( encoding->format )   ||
1628	           FT_READ_BYTE( count )              )
1629	        goto Exit;
1630	
1631	      switch ( encoding->format & 0x7F )
1632	      {
1633	      case 0:
1634	        {
1635	          FT_Byte*  p;
1636	
1637	
1638	          /* By convention, GID 0 is always ".notdef" and is never */
1639	          /* coded in the font.  Hence, the number of codes found  */
1640	          /* in the table is `count+1'.                            */
1641	          /*                                                       */
1642	          encoding->count = count + 1;
1643	
1644	          if ( FT_FRAME_ENTER( count ) )
1645	            goto Exit;
1646	
1647	          p = (FT_Byte*)stream->cursor;
1648	
1649	          for ( j = 1; j <= count; j++ )
1650	          {
1651	            glyph_code = *p++;
1652	
1653	            /* Make sure j is not too big. */
1654	            if ( j < num_glyphs )
1655	            {
1656	              /* Assign code to GID mapping. */
1657	              encoding->codes[glyph_code] = (FT_UShort)j;
1658	
1659	              /* Assign code to SID mapping. */
1660	              encoding->sids[glyph_code] = charset->sids[j];
1661	            }
1662	          }
1663	
1664	          FT_FRAME_EXIT();
1665	        }
1666	        break;
1667	
1668	      case 1:
1669	        {
1670	          FT_UInt  nleft;
1671	          FT_UInt  i = 1;
1672	          FT_UInt  k;
1673	
1674	
1675	          encoding->count = 0;
1676	
1677	          /* Parse the Format1 ranges. */
1678	          for ( j = 0;  j < count; j++, i += nleft )
1679	          {
1680	            /* Read the first glyph code of the range. */
1681	            if ( FT_READ_BYTE( glyph_code ) )
1682	              goto Exit;
1683	
1684	            /* Read the number of codes in the range. */
1685	            if ( FT_READ_BYTE( nleft ) )
1686	              goto Exit;
1687	
1688	            /* Increment nleft, so we read `nleft + 1' codes/sids. */
1689	            nleft++;
1690	
1691	            /* compute max number of character codes */
1692	            if ( (FT_UInt)nleft > encoding->count )
1693	              encoding->count = nleft;
1694	
1695	            /* Fill in the range of codes/sids. */
1696	            for ( k = i; k < nleft + i; k++, glyph_code++ )
1697	            {
1698	              /* Make sure k is not too big. */
1699	              if ( k < num_glyphs && glyph_code < 256 )
1700	              {
1701	                /* Assign code to GID mapping. */
1702	                encoding->codes[glyph_code] = (FT_UShort)k;
1703	
1704	                /* Assign code to SID mapping. */
1705	                encoding->sids[glyph_code] = charset->sids[k];
1706	              }
1707	            }
1708	          }
1709	
1710	          /* simple check; one never knows what can be found in a font */
1711	          if ( encoding->count > 256 )
1712	            encoding->count = 256;
1713	        }
1714	        break;
1715	
1716	      default:
1717	        FT_ERROR(( "cff_encoding_load: invalid table format\n" ));
1718	        error = FT_THROW( Invalid_File_Format );
1719	        goto Exit;
1720	      }
1721	
1722	      /* Parse supplemental encodings, if any. */
1723	      if ( encoding->format & 0x80 )
1724	      {
1725	        FT_UInt  gindex;
1726	
1727	
1728	        /* count supplements */
1729	        if ( FT_READ_BYTE( count ) )
1730	          goto Exit;
1731	
1732	        for ( j = 0; j < count; j++ )
1733	        {
1734	          /* Read supplemental glyph code. */
1735	          if ( FT_READ_BYTE( glyph_code ) )
1736	            goto Exit;
1737	
1738	          /* Read the SID associated with this glyph code. */
1739	          if ( FT_READ_USHORT( glyph_sid ) )
1740	            goto Exit;
1741	
1742	          /* Assign code to SID mapping. */
1743	          encoding->sids[glyph_code] = glyph_sid;
1744	
1745	          /* First, look up GID which has been assigned to */
1746	          /* SID glyph_sid.                                */
1747	          for ( gindex = 0; gindex < num_glyphs; gindex++ )
1748	          {
1749	            if ( charset->sids[gindex] == glyph_sid )
1750	            {
1751	              encoding->codes[glyph_code] = (FT_UShort)gindex;
1752	              break;
1753	            }
1754	          }
1755	        }
1756	      }
1757	    }
1758	    else
1759	    {
1760	      /* We take into account the fact a CFF font can use a predefined */
1761	      /* encoding without containing all of the glyphs encoded by this */
1762	      /* encoding (see the note at the end of section 12 in the CFF    */
1763	      /* specification).                                               */
1764	
1765	      switch ( (FT_UInt)offset )
1766	      {
1767	      case 0:
1768	        /* First, copy the code to SID mapping. */
1769	        FT_ARRAY_COPY( encoding->sids, cff_standard_encoding, 256 );
1770	        goto Populate;
1771	
1772	      case 1:
1773	        /* First, copy the code to SID mapping. */
1774	        FT_ARRAY_COPY( encoding->sids, cff_expert_encoding, 256 );
1775	
1776	      Populate:
1777	        /* Construct code to GID mapping from code to SID mapping */
1778	        /* and charset.                                           */
1779	
1780	        encoding->count = 0;
1781	
1782	        error = cff_charset_compute_cids( charset, num_glyphs,
1783	                                          stream->memory );
1784	        if ( error )
1785	          goto Exit;
1786	
1787	        for ( j = 0; j < 256; j++ )
1788	        {
1789	          FT_UInt  sid = encoding->sids[j];
1790	          FT_UInt  gid = 0;
1791	
1792	
1793	          if ( sid )
1794	            gid = cff_charset_cid_to_gindex( charset, sid );
1795	
1796	          if ( gid != 0 )
1797	          {
1798	            encoding->codes[j] = (FT_UShort)gid;
1799	            encoding->count    = j + 1;
1800	          }
1801	          else
1802	          {
1803	            encoding->codes[j] = 0;
1804	            encoding->sids [j] = 0;
1805	          }
1806	        }
1807	        break;
1808	
1809	      default:
1810	        FT_ERROR(( "cff_encoding_load: invalid table format\n" ));
1811	        error = FT_THROW( Invalid_File_Format );
1812	        goto Exit;
1813	      }
1814	    }
1815	
1816	  Exit:
1817	
1818	    /* Clean up if there was an error. */
1819	    return error;
1820	  }
1821	
1822	
1823	  /* Parse private dictionary; first call is always from `cff_face_init', */
1824	  /* so NDV has not been set for CFF2 variation.                          */
1825	  /*                                                                      */
1826	  /* `cff_slot_load' must call this function each time NDV changes.       */
1827	  static FT_Error
1828	  cff_load_private_dict( CFF_Font     font,
1829	                         CFF_SubFont  subfont,
1830	                         FT_UInt      lenNDV,
1831	                         FT_Fixed*    NDV )
1832	  {
1833	    FT_Error         error  = FT_Err_Ok;
1834	    CFF_ParserRec    parser;
1835	    CFF_FontRecDict  top    = &subfont->font_dict;
1836	    CFF_Private      priv   = &subfont->private_dict;
1837	    FT_Stream        stream = font->stream;
1838	    FT_UInt          stackSize;
1839	
1840	
1841	    if ( !top->private_offset || !top->private_size )
1842	      goto Exit2;       /* no private DICT, do nothing */
1843	
1844	    /* store handle needed to access memory, vstore for blend */
1845	    subfont->blend.font   = font;
1846	    subfont->blend.usedBV = FALSE;  /* clear state */
1847	
1848	    /* set defaults */
1849	    FT_ZERO( priv );
1850	
1851	    priv->blue_shift       = 7;
1852	    priv->blue_fuzz        = 1;
1853	    priv->lenIV            = -1;
1854	    priv->expansion_factor = (FT_Fixed)( 0.06 * 0x10000L );
1855	    priv->blue_scale       = (FT_Fixed)( 0.039625 * 0x10000L * 1000 );
1856	
1857	    /* provide inputs for blend calculations */
1858	    priv->subfont   = subfont;
1859	    subfont->lenNDV = lenNDV;
1860	    subfont->NDV    = NDV;
1861	
1862	    stackSize = font->cff2 ? font->top_font.font_dict.maxstack
1863	                           : CFF_MAX_STACK_DEPTH + 1;
1864	
1865	    if ( cff_parser_init( &parser,
1866	                          font->cff2 ? CFF2_CODE_PRIVATE : CFF_CODE_PRIVATE,
1867	                          priv,
1868	                          font->library,
1869	                          stackSize,
1870	                          top->num_designs,
1871	                          top->num_axes ) )
1872	      goto Exit;
1873	
1874	    if ( FT_STREAM_SEEK( font->base_offset + top->private_offset ) ||
1875	         FT_FRAME_ENTER( top->private_size )                       )
1876	      goto Exit;
1877	
1878	    FT_TRACE4(( " private dictionary:\n" ));
1879	    error = cff_parser_run( &parser,
1880	                            (FT_Byte*)stream->cursor,
1881	                            (FT_Byte*)stream->limit );
1882	    FT_FRAME_EXIT();
1883	
1884	    if ( error )
1885	      goto Exit;
1886	
1887	    /* ensure that `num_blue_values' is even */
1888	    priv->num_blue_values &= ~1;
1889	
1890	  Exit:
1891	    /* clean up */
1892	    cff_blend_clear( subfont ); /* clear blend stack */
1893	    cff_parser_done( &parser ); /* free parser stack */
1894	
1895	  Exit2:
1896	    /* no clean up (parser not initialized) */
1897	    return error;
1898	  }
1899	
1900	
1901	  /* There are 3 ways to call this function, distinguished by code.  */
1902	  /*                                                                 */
1903	  /* . CFF_CODE_TOPDICT for either a CFF Top DICT or a CFF Font DICT */
1904	  /* . CFF2_CODE_TOPDICT for CFF2 Top DICT                           */
1905	  /* . CFF2_CODE_FONTDICT for CFF2 Font DICT                         */
1906	
1907	  static FT_Error
1908	  cff_subfont_load( CFF_SubFont  subfont,
1909	                    CFF_Index    idx,
1910	                    FT_UInt      font_index,
1911	                    FT_Stream    stream,
1912	                    FT_ULong     base_offset,
1913	                    FT_UInt      code,
1914	                    CFF_Font     font )
1915	  {
1916	    FT_Error         error;
1917	    CFF_ParserRec    parser;
1918	    FT_Byte*         dict = NULL;
1919	    FT_ULong         dict_len;
1920	    CFF_FontRecDict  top  = &subfont->font_dict;
1921	    CFF_Private      priv = &subfont->private_dict;
1922	
1923	    FT_Bool  cff2      = ( code == CFF2_CODE_TOPDICT  ||
1924	                           code == CFF2_CODE_FONTDICT );
1925	    FT_UInt  stackSize = cff2 ? CFF2_DEFAULT_STACK
1926	                              : CFF_MAX_STACK_DEPTH;
1927	
1928	
1929	    /* Note: We use default stack size for CFF2 Font DICT because        */
1930	    /*       Top and Font DICTs are not allowed to have blend operators. */
1931	    error = cff_parser_init( &parser,
1932	                             code,
1933	                             &subfont->font_dict,
1934	                             font->library,
1935	                             stackSize,
1936	                             0,
1937	                             0 );
1938	    if ( error )
1939	      goto Exit;
1940	
1941	    /* set defaults */
1942	    FT_ZERO( top );
1943	
1944	    top->underline_position  = -( 100L << 16 );
1945	    top->underline_thickness = 50L << 16;
1946	    top->charstring_type     = 2;
1947	    top->font_matrix.xx      = 0x10000L;
1948	    top->font_matrix.yy      = 0x10000L;
1949	    top->cid_count           = 8720;
1950	
1951	    /* we use the implementation specific SID value 0xFFFF to indicate */
1952	    /* missing entries                                                 */
1953	    top->version             = 0xFFFFU;
1954	    top->notice              = 0xFFFFU;
1955	    top->copyright           = 0xFFFFU;
1956	    top->full_name           = 0xFFFFU;
1957	    top->family_name         = 0xFFFFU;
1958	    top->weight              = 0xFFFFU;
1959	    top->embedded_postscript = 0xFFFFU;
1960	
1961	    top->cid_registry        = 0xFFFFU;
1962	    top->cid_ordering        = 0xFFFFU;
1963	    top->cid_font_name       = 0xFFFFU;
1964	
1965	    /* set default stack size */
1966	    top->maxstack            = cff2 ? CFF2_DEFAULT_STACK : 48;
1967	
1968	    if ( idx->count )   /* count is nonzero for a real index */
1969	      error = cff_index_access_element( idx, font_index, &dict, &dict_len );
1970	    else
1971	    {
1972	      /* CFF2 has a fake top dict index;     */
1973	      /* simulate `cff_index_access_element' */
1974	
1975	      /* Note: macros implicitly use `stream' and set `error' */
1976	      if ( FT_STREAM_SEEK( idx->data_offset )       ||
1977	           FT_FRAME_EXTRACT( idx->data_size, dict ) )
1978	        goto Exit;
1979	
1980	      dict_len = idx->data_size;
1981	    }
1982	
1983	    if ( !error )
1984	    {
1985	      FT_TRACE4(( " top dictionary:\n" ));
1986	      error = cff_parser_run( &parser, dict, dict + dict_len );
1987	    }
1988	
1989	    /* clean up regardless of error */
1990	    if ( idx->count )
1991	      cff_index_forget_element( idx, &dict );
1992	    else
1993	      FT_FRAME_RELEASE( dict );
1994	
1995	    if ( error )
1996	      goto Exit;
1997	
1998	    /* if it is a CID font, we stop there */
1999	    if ( top->cid_registry != 0xFFFFU )
2000	      goto Exit;
2001	
2002	    /* Parse the private dictionary, if any.                   */
2003	    /*                                                         */
2004	    /* CFF2 does not have a private dictionary in the Top DICT */
2005	    /* but may have one in a Font DICT.  We need to parse      */
2006	    /* the latter here in order to load any local subrs.       */
2007	    error = cff_load_private_dict( font, subfont, 0, 0 );
2008	    if ( error )
2009	      goto Exit;
2010	
2011	    /* read the local subrs, if any */
2012	    if ( priv->local_subrs_offset )
2013	    {
2014	      if ( FT_STREAM_SEEK( base_offset + top->private_offset +
2015	                           priv->local_subrs_offset ) )
2016	        goto Exit;
2017	
2018	      error = cff_index_init( &subfont->local_subrs_index, stream, 1, cff2 );
2019	      if ( error )
2020	        goto Exit;
2021	
2022	      error = cff_index_get_pointers( &subfont->local_subrs_index,
2023	                                      &subfont->local_subrs, NULL, NULL );
2024	      if ( error )
2025	        goto Exit;
2026	    }
2027	
2028	  Exit:
2029	    cff_parser_done( &parser ); /* free parser stack */
2030	
2031	    return error;
2032	  }
2033	
2034	
2035	  static void
2036	  cff_subfont_done( FT_Memory    memory,
2037	                    CFF_SubFont  subfont )
2038	  {
2039	    if ( subfont )
2040	    {
2041	      cff_index_done( &subfont->local_subrs_index );
2042	      FT_FREE( subfont->local_subrs );
2043	
2044	      FT_FREE( subfont->blend.lastNDV );
2045	      FT_FREE( subfont->blend.BV );
2046	      FT_FREE( subfont->blend_stack );
2047	    }
2048	  }
2049	
2050	
2051	  FT_LOCAL_DEF( FT_Error )
2052	  cff_font_load( FT_Library library,
2053	                 FT_Stream  stream,
2054	                 FT_Int     face_index,
2055	                 CFF_Font   font,
2056	                 FT_Bool    pure_cff,
2057	                 FT_Bool    cff2 )
2058	  {
2059	    static const FT_Frame_Field  cff_header_fields[] =
2060	    {
2061	#undef  FT_STRUCTURE
2062	#define FT_STRUCTURE  CFF_FontRec
2063	
2064	      FT_FRAME_START( 3 ),
2065	        FT_FRAME_BYTE( version_major ),
2066	        FT_FRAME_BYTE( version_minor ),
2067	        FT_FRAME_BYTE( header_size ),
2068	      FT_FRAME_END
2069	    };
2070	
2071	    FT_Error         error;
2072	    FT_Memory        memory = stream->memory;
2073	    FT_ULong         base_offset;
2074	    CFF_FontRecDict  dict;
2075	    CFF_IndexRec     string_index;
2076	    FT_UInt          subfont_index;
2077	
2078	
2079	    FT_ZERO( font );
2080	    FT_ZERO( &string_index );
2081	
2082	    dict        = &font->top_font.font_dict;
2083	    base_offset = FT_STREAM_POS();
2084	
2085	    font->library     = library;
2086	    font->stream      = stream;
2087	    font->memory      = memory;
2088	    font->cff2        = cff2;
2089	    font->base_offset = base_offset;
2090	
2091	    /* read CFF font header */
2092	    if ( FT_STREAM_READ_FIELDS( cff_header_fields, font ) )
2093	      goto Exit;
2094	
2095	    if ( cff2 )
2096	    {
2097	      if ( font->version_major != 2 ||
2098	           font->header_size < 5    )
2099	      {
2100	        FT_TRACE2(( "  not a CFF2 font header\n" ));
2101	        error = FT_THROW( Unknown_File_Format );
2102	        goto Exit;
2103	      }
2104	
2105	      if ( FT_READ_USHORT( font->top_dict_length ) )
2106	        goto Exit;
2107	    }
2108	    else
2109	    {
2110	      if ( font->version_major != 1 ||
2111	           font->header_size < 4    )
2112	      {
2113	        FT_TRACE2(( "  not a CFF font header\n" ));
2114	        error = FT_THROW( Unknown_File_Format );
2115	        goto Exit;
2116	      }
2117	    }
2118	
2119	    /* skip the rest of the header */
2120	    if ( FT_STREAM_SEEK( base_offset + font->header_size ) )
2121	      goto Exit;
2122	
2123	    if ( cff2 )
2124	    {
2125	      /* For CFF2, the top dict data immediately follow the header    */
2126	      /* and the length is stored in the header `offSize' field;      */
2127	      /* there is no index for it.                                    */
2128	      /*                                                              */
2129	      /* Use the `font_dict_index' to save the current position       */
2130	      /* and length of data, but leave count at zero as an indicator. */
2131	      FT_ZERO( &font->font_dict_index );
2132	
2133	      font->font_dict_index.data_offset = FT_STREAM_POS();
2134	      font->font_dict_index.data_size   = font->top_dict_length;
2135	
2136	      /* skip the top dict data for now, we will parse it later */
2137	      if ( FT_STREAM_SKIP( font->top_dict_length ) )
2138	        goto Exit;
2139	
2140	      /* next, read the global subrs index */
2141	      if ( FT_SET_ERROR( cff_index_init( &font->global_subrs_index,
2142	                                         stream, 1, cff2 ) ) )
2143	        goto Exit;
2144	    }
2145	    else
2146	    {
2147	      /* for CFF, read the name, top dict, string and global subrs index */
2148	      if ( FT_SET_ERROR( cff_index_init( &font->name_index,
2149	                                         stream, 0, cff2 ) )                 ||
2150	           FT_SET_ERROR( cff_index_init( &font->font_dict_index,
2151	                                         stream, 0, cff2 ) )                 ||
2152	           FT_SET_ERROR( cff_index_init( &string_index,
2153	                                         stream, 1, cff2 ) )                 ||
2154	           FT_SET_ERROR( cff_index_init( &font->global_subrs_index,
2155	                                         stream, 1, cff2 ) )                 ||
2156	           FT_SET_ERROR( cff_index_get_pointers( &string_index,
2157	                                                 &font->strings,
2158	                                                 &font->string_pool,
2159	                                                 &font->string_pool_size ) ) )
2160	        goto Exit;
2161	    }
2162	
2163	    font->num_strings = string_index.count;
2164	
2165	    if ( pure_cff )
2166	    {
2167	      /* well, we don't really forget the `disabled' fonts... */
2168	      subfont_index = (FT_UInt)( face_index & 0xFFFF );
2169	
2170	      if ( face_index > 0 && subfont_index >= font->name_index.count )
2171	      {
2172	        FT_ERROR(( "cff_font_load:"
2173	                   " invalid subfont index for pure CFF font (%d)\n",
2174	                   subfont_index ));
2175	        error = FT_THROW( Invalid_Argument );
2176	        goto Exit;
2177	      }
2178	
2179	      font->num_faces = font->name_index.count;
2180	    }
2181	    else
2182	    {
2183	      subfont_index = 0;
2184	
2185	      if ( font->name_index.count > 1 )
2186	      {
2187	        FT_ERROR(( "cff_font_load:"
2188	                   " invalid CFF font with multiple subfonts\n"
2189	                   "              "
2190	                   " in SFNT wrapper\n" ));
2191	        error = FT_THROW( Invalid_File_Format );
2192	        goto Exit;
2193	      }
2194	    }
2195	
2196	    /* in case of a font format check, simply exit now */
2197	    if ( face_index < 0 )
2198	      goto Exit;
2199	
2200	    /* now, parse the top-level font dictionary */
2201	    FT_TRACE4(( "parsing top-level\n" ));
2202	    error = cff_subfont_load( &font->top_font,
2203	                              &font->font_dict_index,
2204	                              subfont_index,
2205	                              stream,
2206	                              base_offset,
2207	                              cff2 ? CFF2_CODE_TOPDICT : CFF_CODE_TOPDICT,
2208	                              font );
2209	    if ( error )
2210	      goto Exit;
2211	
2212	    if ( FT_STREAM_SEEK( base_offset + dict->charstrings_offset ) )
2213	      goto Exit;
2214	
2215	    error = cff_index_init( &font->charstrings_index, stream, 0, cff2 );
2216	    if ( error )
2217	      goto Exit;
2218	
2219	    /* now, check for a CID or CFF2 font */
2220	    if ( dict->cid_registry != 0xFFFFU ||
2221	         cff2                          )
2222	    {
2223	      CFF_IndexRec  fd_index;
2224	      CFF_SubFont   sub = NULL;
2225	      FT_UInt       idx;
2226	
2227	
2228	      /* for CFF2, read the Variation Store if available;                 */
2229	      /* this must follow the Top DICT parse and precede any Private DICT */
2230	      error = cff_vstore_load( &font->vstore,
2231	                               stream,
2232	                               base_offset,
2233	                               dict->vstore_offset );
2234	      if ( error )
2235	        goto Exit;
2236	
2237	      /* this is a CID-keyed font, we must now allocate a table of */
2238	      /* sub-fonts, then load each of them separately              */
2239	      if ( FT_STREAM_SEEK( base_offset + dict->cid_fd_array_offset ) )
2240	        goto Exit;
2241	
2242	      error = cff_index_init( &fd_index, stream, 0, cff2 );
2243	      if ( error )
2244	        goto Exit;
2245	
2246	      /* Font Dicts are not limited to 256 for CFF2. */
2247	      /* TODO: support this for CFF2                 */
2248	      if ( fd_index.count > CFF_MAX_CID_FONTS )
2249	      {
2250	        FT_TRACE0(( "cff_font_load: FD array too large in CID font\n" ));
2251	        goto Fail_CID;
2252	      }
2253	
2254	      /* allocate & read each font dict independently */
2255	      font->num_subfonts = fd_index.count;
2256	      if ( FT_NEW_ARRAY( sub, fd_index.count ) )
2257	        goto Fail_CID;
2258	
2259	      /* set up pointer table */
2260	      for ( idx = 0; idx < fd_index.count; idx++ )
2261	        font->subfonts[idx] = sub + idx;
2262	
2263	      /* now load each subfont independently */
2264	      for ( idx = 0; idx < fd_index.count; idx++ )
2265	      {
2266	        sub = font->subfonts[idx];
2267	        FT_TRACE4(( "parsing subfont %u\n", idx ));
2268	        error = cff_subfont_load( sub,
2269	                                  &fd_index,
2270	                                  idx,
2271	                                  stream,
2272	                                  base_offset,
2273	                                  cff2 ? CFF2_CODE_FONTDICT
2274	                                       : CFF_CODE_TOPDICT,
2275	                                  font );
2276	        if ( error )
2277	          goto Fail_CID;
2278	      }
2279	
2280	      /* now load the FD Select array;               */
2281	      /* CFF2 omits FDSelect if there is only one FD */
2282	      if ( !cff2 || fd_index.count > 1 )
2283	        error = CFF_Load_FD_Select( &font->fd_select,
2284	                                    font->charstrings_index.count,
2285	                                    stream,
2286	                                    base_offset + dict->cid_fd_select_offset );
2287	
2288	    Fail_CID:
2289	      cff_index_done( &fd_index );
2290	
2291	      if ( error )
2292	        goto Exit;
2293	    }
2294	    else
2295	      font->num_subfonts = 0;
2296	
2297	    /* read the charstrings index now */
2298	    if ( dict->charstrings_offset == 0 )
2299	    {
2300	      FT_ERROR(( "cff_font_load: no charstrings offset\n" ));
2301	      error = FT_THROW( Invalid_File_Format );
2302	      goto Exit;
2303	    }
2304	
2305	    font->num_glyphs = font->charstrings_index.count;
2306	
2307	    error = cff_index_get_pointers( &font->global_subrs_index,
2308	                                    &font->global_subrs, NULL, NULL );
2309	
2310	    if ( error )
2311	      goto Exit;
2312	
2313	    /* read the Charset and Encoding tables if available */
2314	    if ( !cff2 && font->num_glyphs > 0 )
2315	    {
2316	      FT_Bool  invert = FT_BOOL( dict->cid_registry != 0xFFFFU && pure_cff );
2317	
2318	
2319	      error = cff_charset_load( &font->charset, font->num_glyphs, stream,
2320	                                base_offset, dict->charset_offset, invert );
2321	      if ( error )
2322	        goto Exit;
2323	
2324	      /* CID-keyed CFFs don't have an encoding */
2325	      if ( dict->cid_registry == 0xFFFFU )
2326	      {
2327	        error = cff_encoding_load( &font->encoding,
2328	                                   &font->charset,
2329	                                   font->num_glyphs,
2330	                                   stream,
2331	                                   base_offset,
2332	                                   dict->encoding_offset );
2333	        if ( error )
2334	          goto Exit;
2335	      }
2336	    }
2337	
2338	    /* get the font name (/CIDFontName for CID-keyed fonts, */
2339	    /* /FontName otherwise)                                 */
2340	    font->font_name = cff_index_get_name( font, subfont_index );
2341	
2342	  Exit:
2343	    cff_index_done( &string_index );
2344	
2345	    return error;
2346	  }
2347	
2348	
2349	  FT_LOCAL_DEF( void )
2350	  cff_font_done( CFF_Font  font )
2351	  {
2352	    FT_Memory  memory = font->memory;
2353	    FT_UInt    idx;
2354	
2355	
2356	    cff_index_done( &font->global_subrs_index );
2357	    cff_index_done( &font->font_dict_index );
2358	    cff_index_done( &font->name_index );
2359	    cff_index_done( &font->charstrings_index );
2360	
2361	    /* release font dictionaries, but only if working with */
2362	    /* a CID keyed CFF font or a CFF2 font                 */
2363	    if ( font->num_subfonts > 0 )
2364	    {
2365	      for ( idx = 0; idx < font->num_subfonts; idx++ )
2366	        cff_subfont_done( memory, font->subfonts[idx] );
2367	
2368	      /* the subfonts array has been allocated as a single block */
2369	      FT_FREE( font->subfonts[0] );
2370	    }
2371	
2372	    cff_encoding_done( &font->encoding );
2373	    cff_charset_done( &font->charset, font->stream );
2374	    cff_vstore_done( &font->vstore, memory );
2375	
2376	    cff_subfont_done( memory, &font->top_font );
2377	
2378	    CFF_Done_FD_Select( &font->fd_select, font->stream );
2379	
2380	    FT_FREE( font->font_info );
2381	
2382	    FT_FREE( font->font_name );
2383	    FT_FREE( font->global_subrs );
2384	    FT_FREE( font->strings );
2385	    FT_FREE( font->string_pool );
2386	
2387	    if ( font->cf2_instance.finalizer )
2388	    {
2389	      font->cf2_instance.finalizer( font->cf2_instance.data );
2390	      FT_FREE( font->cf2_instance.data );
2391	    }
2392	  }
