335	  static FT_Error
336	  cff_index_load_offsets( CFF_Index  idx )
337	  {
338	    FT_Error   error  = FT_Err_Ok;
339	    FT_Stream  stream = idx->stream;
340	    FT_Memory  memory = stream->memory;
341	
342	
343	    if ( idx->count > 0 && idx->offsets == NULL )
344	    {
345	      FT_Byte    offsize = idx->off_size;
346	      FT_ULong   data_size;
347	      FT_Byte*   p;
348	      FT_Byte*   p_end;
349	      FT_ULong*  poff;
350	
351	
352	      data_size = (FT_ULong)( idx->count + 1 ) * offsize;
353	
354	      if ( FT_NEW_ARRAY( idx->offsets, idx->count + 1 ) ||
355	           FT_STREAM_SEEK( idx->start + idx->hdr_size ) ||
356	           FT_FRAME_ENTER( data_size )                  )
357	        goto Exit;
358	
359	      poff   = idx->offsets;
360	      p      = (FT_Byte*)stream->cursor;
361	      p_end  = p + data_size;
362	
363	      switch ( offsize )
364	      {
365	      case 1:
366	        for ( ; p < p_end; p++, poff++ )
367	          poff[0] = p[0];
368	        break;
369	
370	      case 2:
371	        for ( ; p < p_end; p += 2, poff++ )
372	          poff[0] = FT_PEEK_USHORT( p );
373	        break;
374	
375	      case 3:
376	        for ( ; p < p_end; p += 3, poff++ )
377	          poff[0] = FT_PEEK_UOFF3( p );
378	        break;
379	
380	      default:
381	        for ( ; p < p_end; p += 4, poff++ )
382	          poff[0] = FT_PEEK_ULONG( p );
383	      }
384	
385	      FT_FRAME_EXIT();
386	    }
387	
388	  Exit:
389	    if ( error )
390	      FT_FREE( idx->offsets );
391	
392	    return error;
393	  }
394	
395	
396	  /* Allocate a table containing pointers to an index's elements. */
397	  /* The `pool' argument makes this function convert the index    */
398	  /* entries to C-style strings (this is, NULL-terminated).       */
399	  static FT_Error
400	  cff_index_get_pointers( CFF_Index   idx,
401	                          FT_Byte***  table,
402	                          FT_Byte**   pool,
403	                          FT_ULong*   pool_size )
404	  {
405	    FT_Error   error     = FT_Err_Ok;
406	    FT_Memory  memory    = idx->stream->memory;
407	
408	    FT_Byte**  t         = NULL;
409	    FT_Byte*   new_bytes = NULL;
410	    FT_ULong   new_size;
411	
412	
413	    *table = NULL;
414	
415	    if ( idx->offsets == NULL )
416	    {
417	      error = cff_index_load_offsets( idx );
418	      if ( error )
419	        goto Exit;
420	    }
421	
422	    new_size = idx->data_size + idx->count;
423	
424	    if ( idx->count > 0                                &&
425	         !FT_NEW_ARRAY( t, idx->count + 1 )            &&
426	         ( !pool || !FT_ALLOC( new_bytes, new_size ) ) )
427	    {
428	      FT_ULong  n, cur_offset;
429	      FT_ULong  extra = 0;
430	      FT_Byte*  org_bytes = idx->bytes;
431	
432	
433	      /* at this point, `idx->offsets' can't be NULL */
434	      cur_offset = idx->offsets[0] - 1;
435	
436	      /* sanity check */
437	      if ( cur_offset != 0 )
438	      {
439	        FT_TRACE0(( "cff_index_get_pointers:"
440	                    " invalid first offset value %d set to zero\n",
441	                    cur_offset ));
442	        cur_offset = 0;
443	      }
444	
445	      if ( !pool )
446	        t[0] = org_bytes + cur_offset;
447	      else
448	        t[0] = new_bytes + cur_offset;
449	
450	      for ( n = 1; n <= idx->count; n++ )
451	      {
452	        FT_ULong  next_offset = idx->offsets[n] - 1;
453	
454	
455	        /* two sanity checks for invalid offset tables */
456	        if ( next_offset < cur_offset )
457	          next_offset = cur_offset;
458	        else if ( next_offset > idx->data_size )
459	          next_offset = idx->data_size;
460	
461	        if ( !pool )
462	          t[n] = org_bytes + next_offset;
463	        else
464	        {
465	          t[n] = new_bytes + next_offset + extra;
466	
467	          if ( next_offset != cur_offset )
468	          {
469	            FT_MEM_COPY( t[n - 1], org_bytes + cur_offset, t[n] - t[n - 1] );
470	            t[n][0] = '\0';
471	            t[n]   += 1;
472	            extra++;
473	          }
474	        }
475	
476	        cur_offset = next_offset;
477	      }
478	      *table = t;
479	
480	      if ( pool )
481	        *pool = new_bytes;
482	      if ( pool_size )
483	        *pool_size = new_size;
484	    }
485	
486	  Exit:
487	    return error;
488	  }
