818	
819	  static FT_Error
820	  cff_charset_compute_cids( CFF_Charset  charset,
821	                            FT_UInt      num_glyphs,
822	                            FT_Memory    memory )
823	  {
824	    FT_Error   error   = FT_Err_Ok;
825	    FT_UInt    i;
826	    FT_Long    j;
827	    FT_UShort  max_cid = 0;
828	
829	
830	    if ( charset->max_cid > 0 )
831	      goto Exit;
832	
833	    for ( i = 0; i < num_glyphs; i++ )
834	    {
835	      if ( charset->sids[i] > max_cid )
836	        max_cid = charset->sids[i];
837	    }
838	
839	    if ( FT_NEW_ARRAY( charset->cids, (FT_ULong)max_cid + 1 ) )
840	      goto Exit;
841	
842	    /* When multiple GIDs map to the same CID, we choose the lowest */
843	    /* GID.  This is not described in any spec, but it matches the  */
844	    /* behaviour of recent Acroread versions.                       */
845	    for ( j = (FT_Long)num_glyphs - 1; j >= 0; j-- )
846	      charset->cids[charset->sids[j]] = (FT_UShort)j;
847	
848	    charset->max_cid    = max_cid;
849	    charset->num_glyphs = num_glyphs;
850	
851	  Exit:
852	    return error;
853	  }
854	
855	
856	  FT_LOCAL_DEF( FT_UInt )
857	  cff_charset_cid_to_gindex( CFF_Charset  charset,
858	                             FT_UInt      cid )
859	  {
860	    FT_UInt  result = 0;
861	
862	
863	    if ( cid <= charset->max_cid )
864	      result = charset->cids[cid];
865	
866	    return result;
867	  }
