79	  FT_LOCAL_DEF( void )
80	  cff_parser_done( CFF_Parser  parser )
81	  {
82	    FT_Memory  memory = parser->library->memory;    /* for FT_FREE */
83	
84	
85	    FT_FREE( parser->stack );
86	  }
