563	  static FT_Error
564	  cff_parse_font_matrix( CFF_Parser  parser )
565	  {
566	    CFF_FontRecDict  dict   = (CFF_FontRecDict)parser->object;
567	    FT_Matrix*       matrix = &dict->font_matrix;
568	    FT_Vector*       offset = &dict->font_offset;
569	    FT_ULong*        upm    = &dict->units_per_em;
570	    FT_Byte**        data   = parser->stack;
571	    FT_Error         error  = FT_ERR( Stack_Underflow );
572	
573	
574	    if ( parser->top >= parser->stack + 6 )
575	    {
576	      FT_Fixed  values[6];
577	      FT_Long   scalings[6];
578	
579	      FT_Long  min_scaling, max_scaling;
580	      int      i;
581	
582	
583	      error = FT_Err_Ok;
584	
585	      dict->has_font_matrix = TRUE;
586	
587	      /* We expect a well-formed font matrix, this is, the matrix elements */
588	      /* `xx' and `yy' are of approximately the same magnitude.  To avoid  */
589	      /* loss of precision, we use the magnitude of the largest matrix     */
590	      /* element to scale all other elements.  The scaling factor is then  */
591	      /* contained in the `units_per_em' value.                            */
592	
593	      max_scaling = FT_LONG_MIN;
594	      min_scaling = FT_LONG_MAX;
595	
596	      for ( i = 0; i < 6; i++ )
597	      {
598	        values[i] = cff_parse_fixed_dynamic( parser, data++, &scalings[i] );
599	        if ( values[i] )
600	        {
601	          if ( scalings[i] > max_scaling )
602	            max_scaling = scalings[i];
603	          if ( scalings[i] < min_scaling )
604	            min_scaling = scalings[i];
605	        }
606	      }
607	
608	      if ( max_scaling < -9                  ||
609	           max_scaling > 0                   ||
610	           ( max_scaling - min_scaling ) < 0 ||
611	           ( max_scaling - min_scaling ) > 9 )
612	      {
613	        /* Return default matrix in case of unlikely values. */
614	
615	        FT_TRACE1(( "cff_parse_font_matrix:"
616	                    " strange scaling values (minimum %d, maximum %d),\n"
617	                    "                      "
618	                    " using default matrix\n", min_scaling, max_scaling ));
619	
620	        matrix->xx = 0x10000L;
621	        matrix->yx = 0;
622	        matrix->xy = 0;
623	        matrix->yy = 0x10000L;
624	        offset->x  = 0;
625	        offset->y  = 0;
626	        *upm       = 1;
627	
628	        goto Exit;
629	      }
630	
631	      for ( i = 0; i < 6; i++ )
632	      {
633	        FT_Fixed  value = values[i];
634	        FT_Long   divisor, half_divisor;
635	
636	
637	        if ( !value )
638	          continue;
639	
640	        divisor      = power_tens[max_scaling - scalings[i]];
641	        half_divisor = divisor >> 1;
642	
643	        if ( value < 0 )
644	        {
645	          if ( FT_LONG_MIN + half_divisor < value )
646	            values[i] = ( value - half_divisor ) / divisor;
647	          else
648	            values[i] = FT_LONG_MIN / divisor;
649	        }
650	        else
651	        {
652	          if ( FT_LONG_MAX - half_divisor > value )
653	            values[i] = ( value + half_divisor ) / divisor;
654	          else
655	            values[i] = FT_LONG_MAX / divisor;
656	        }
657	      }
658	
659	      matrix->xx = values[0];
660	      matrix->yx = values[1];
661	      matrix->xy = values[2];
662	      matrix->yy = values[3];
663	      offset->x  = values[4];
664	      offset->y  = values[5];
665	
666	      *upm = (FT_ULong)power_tens[-max_scaling];
667	
668	      FT_TRACE4(( " [%f %f %f %f %f %f]\n",
669	                  (double)matrix->xx / *upm / 65536,
670	                  (double)matrix->xy / *upm / 65536,
671	                  (double)matrix->yx / *upm / 65536,
672	                  (double)matrix->yy / *upm / 65536,
673	                  (double)offset->x  / *upm / 65536,
674	                  (double)offset->y  / *upm / 65536 ));
675	    }
676	
677	  Exit:
678	    return error;
679	  }
