838	  static FT_Error
839	  cff_parse_vsindex( CFF_Parser  parser )
840	  {
841	    /* vsindex operator can only be used in a Private DICT */
842	    CFF_Private  priv = (CFF_Private)parser->object;
843	    FT_Byte**    data = parser->stack;
844	    CFF_Blend    blend;
845	    FT_Error     error;
846	
847	
848	    if ( !priv || !priv->subfont )
849	    {
850	      error = FT_THROW( Invalid_File_Format );
851	      goto Exit;
852	    }
853	
854	    blend = &priv->subfont->blend;
855	
856	    if ( blend->usedBV )
857	    {
858	      FT_ERROR(( " cff_parse_vsindex: vsindex not allowed after blend\n" ));
859	      error = FT_THROW( Syntax_Error );
860	      goto Exit;
861	    }
862	
863	    priv->vsindex = (FT_UInt)cff_parse_num( parser, data++ );
864	
865	    FT_TRACE4(( " %d\n", priv->vsindex ));
866	
867	    error = FT_Err_Ok;
868	
869	  Exit:
870	    return error;
871	  }
