89	  /* read an integer */
90	  static FT_Long
91	  cff_parse_integer( FT_Byte*  start,
92	                     FT_Byte*  limit )
93	  {
94	    FT_Byte*  p   = start;
95	    FT_Int    v   = *p++;
96	    FT_Long   val = 0;
97	
98	
99	    if ( v == 28 )
100	    {
101	      if ( p + 2 > limit )
102	        goto Bad;
103	
104	      val = (FT_Short)( ( (FT_UShort)p[0] << 8 ) | p[1] );
105	    }
106	    else if ( v == 29 )
107	    {
108	      if ( p + 4 > limit )
109	        goto Bad;
110	
111	      val = (FT_Long)( ( (FT_ULong)p[0] << 24 ) |
112	                       ( (FT_ULong)p[1] << 16 ) |
113	                       ( (FT_ULong)p[2] <<  8 ) |
114	                         (FT_ULong)p[3]         );
115	    }
116	    else if ( v < 247 )
117	    {
118	      val = v - 139;
119	    }
120	    else if ( v < 251 )
121	    {
122	      if ( p + 1 > limit )
123	        goto Bad;
124	
125	      val = ( v - 247 ) * 256 + p[0] + 108;
126	    }
127	    else
128	    {
129	      if ( p + 1 > limit )
130	        goto Bad;
131	
132	      val = -( v - 251 ) * 256 - p[0] - 108;
133	    }
134	
135	  Exit:
136	    return val;
137	
138	  Bad:
139	    val = 0;
140	    FT_TRACE4(( "!!!END OF DATA:!!!" ));
141	    goto Exit;
142	  }
