144	
145	  static const FT_Long power_tens[] =
146	  {
147	    1L,
148	    10L,
149	    100L,
150	    1000L,
151	    10000L,
152	    100000L,
153	    1000000L,
154	    10000000L,
155	    100000000L,
156	    1000000000L
157	  };
