460	
461	  /* read a floating point number, either integer or real */
462	  static FT_Fixed
463	  do_fixed( CFF_Parser  parser,
464	            FT_Byte**   d,
465	            FT_Long     scaling )
466	  {
467	    if ( **d == 30 )
468	      return cff_parse_real( *d, parser->limit, scaling, NULL );
469	    else
470	    {
471	      FT_Long  val = cff_parse_integer( *d, parser->limit );
472	
473	
474	      if ( scaling )
475	        val *= power_tens[scaling];
476	
477	      if ( val > 0x7FFF )
478	      {
479	        val = 0x7FFFFFFFL;
480	        goto Overflow;
481	      }
482	      else if ( val < -0x7FFF )
483	      {
484	        val = -0x7FFFFFFFL;
485	        goto Overflow;
486	      }
487	
488	      return (FT_Long)( (FT_ULong)val << 16 );
489	
490	    Overflow:
491	      FT_TRACE4(( "!!!OVERFLOW:!!!" ));
492	      return val;
493	    }
494	  }
495	
496	
497	  /* read a floating point number, either integer or real */
498	  static FT_Fixed
499	  cff_parse_fixed( CFF_Parser  parser,
500	                   FT_Byte**   d )
501	  {
502	    return do_fixed( parser, d, 0 );
503	  }
504	
505	
506	  /* read a floating point number, either integer or real, */
507	  /* but return `10^scaling' times the number read in      */
508	  static FT_Fixed
509	  cff_parse_fixed_scaled( CFF_Parser  parser,
510	                          FT_Byte**   d,
511	                          FT_Long     scaling )
512	  {
513	    return do_fixed( parser, d, scaling );
514	  }
515	
516	
517	  /* read a floating point number, either integer or real,     */
518	  /* and return it as precise as possible -- `scaling' returns */
519	  /* the scaling factor (as a power of 10)                     */
520	  static FT_Fixed
521	  cff_parse_fixed_dynamic( CFF_Parser  parser,
522	                           FT_Byte**   d,
523	                           FT_Long*    scaling )
524	  {
525	    FT_ASSERT( scaling );
526	
527	    if ( **d == 30 )
528	      return cff_parse_real( *d, parser->limit, 0, scaling );
529	    else
530	    {
531	      FT_Long  number;
532	      FT_Int   integer_length;
533	
534	
535	      number = cff_parse_integer( d[0], d[1] );
536	
537	      if ( number > 0x7FFFL )
538	      {
539	        for ( integer_length = 5; integer_length < 10; integer_length++ )
540	          if ( number < power_tens[integer_length] )
541	            break;
542	
543	        if ( ( number / power_tens[integer_length - 5] ) > 0x7FFFL )
544	        {
545	          *scaling = integer_length - 4;
546	          return FT_DivFix( number, power_tens[integer_length - 4] );
547	        }
548	        else
549	        {
550	          *scaling = integer_length - 5;
551	          return FT_DivFix( number, power_tens[integer_length - 5] );
552	        }
553	      }
554	      else
555	      {
556	        *scaling = 0;
557	        return (FT_Long)( (FT_ULong)number << 16 );
558	      }
559	    }
560	  }
