711	
712	  static FT_Error
713	  cff_parse_private_dict( CFF_Parser  parser )
714	  {
715	    CFF_FontRecDict  dict = (CFF_FontRecDict)parser->object;
716	    FT_Byte**        data = parser->stack;
717	    FT_Error         error;
718	
719	
720	    error = FT_ERR( Stack_Underflow );
721	
722	    if ( parser->top >= parser->stack + 2 )
723	    {
724	      FT_Long  tmp;
725	
726	
727	      tmp = cff_parse_num( parser, data++ );
728	      if ( tmp < 0 )
729	      {
730	        FT_ERROR(( "cff_parse_private_dict: Invalid dictionary size\n" ));
731	        error = FT_THROW( Invalid_File_Format );
732	        goto Fail;
733	      }
734	      dict->private_size = (FT_ULong)tmp;
735	
736	      tmp = cff_parse_num( parser, data );
737	      if ( tmp < 0 )
738	      {
739	        FT_ERROR(( "cff_parse_private_dict: Invalid dictionary offset\n" ));
740	        error = FT_THROW( Invalid_File_Format );
741	        goto Fail;
742	      }
743	      dict->private_offset = (FT_ULong)tmp;
744	
745	      FT_TRACE4(( " %lu %lu\n",
746	                  dict->private_size, dict->private_offset ));
747	
748	      error = FT_Err_Ok;
749	    }
750	
751	  Fail:
752	    return error;
753	  }
