756	  /* The `MultipleMaster' operator comes before any  */
757	  /* top DICT operators that contain T2 charstrings. */
758	
759	  static FT_Error
760	  cff_parse_multiple_master( CFF_Parser  parser )
761	  {
762	    CFF_FontRecDict  dict = (CFF_FontRecDict)parser->object;
763	    FT_Error         error;
764	
765	
766	#ifdef FT_DEBUG_LEVEL_TRACE
767	    /* beautify tracing message */
768	    if ( ft_trace_levels[FT_COMPONENT] < 4 )
769	      FT_TRACE1(( "Multiple Master CFFs not supported yet,"
770	                  " handling first master design only\n" ));
771	    else
772	      FT_TRACE1(( " (not supported yet,"
773	                  " handling first master design only)\n" ));
774	#endif
775	
776	    error = FT_ERR( Stack_Underflow );
777	
778	    /* currently, we handle only the first argument */
779	    if ( parser->top >= parser->stack + 5 )
780	    {
781	      FT_Long  num_designs = cff_parse_num( parser, parser->stack );
782	
783	
784	      if ( num_designs > 16 || num_designs < 2 )
785	      {
786	        FT_ERROR(( "cff_parse_multiple_master:"
787	                   " Invalid number of designs\n" ));
788	        error = FT_THROW( Invalid_File_Format );
789	      }
790	      else
791	      {
792	        dict->num_designs   = (FT_UShort)num_designs;
793	        dict->num_axes      = (FT_UShort)( parser->top - parser->stack - 4 );
794	
795	        parser->num_designs = dict->num_designs;
796	        parser->num_axes    = dict->num_axes;
797	
798	        error = FT_Err_Ok;
799	      }
800	    }
801	
802	    return error;
803	  }
