807	  cff_parse_cid_ros( CFF_Parser  parser )
808	  {
809	    CFF_FontRecDict  dict = (CFF_FontRecDict)parser->object;
810	    FT_Byte**        data = parser->stack;
811	    FT_Error         error;
812	
813	
814	    error = FT_ERR( Stack_Underflow );
815	
816	    if ( parser->top >= parser->stack + 3 )
817	    {
818	      dict->cid_registry = (FT_UInt)cff_parse_num( parser, data++ );
819	      dict->cid_ordering = (FT_UInt)cff_parse_num( parser, data++ );
