923	  static FT_Error
924	  cff_parse_maxstack( CFF_Parser  parser )
925	  {
926	    /* maxstack operator can only be used in a Top DICT */
927	    CFF_FontRecDict  dict  = (CFF_FontRecDict)parser->object;
928	    FT_Byte**        data  = parser->stack;
929	    FT_Error         error = FT_Err_Ok;
930	
931	
932	    if ( !dict )
933	    {
934	      error = FT_THROW( Invalid_File_Format );
935	      goto Exit;
936	    }
937	
938	    dict->maxstack = (FT_UInt)cff_parse_num( parser, data++ );
939	    if ( dict->maxstack > CFF2_MAX_STACK )
940	      dict->maxstack = CFF2_MAX_STACK;
941	    if ( dict->maxstack < CFF2_DEFAULT_STACK )
942	      dict->maxstack = CFF2_DEFAULT_STACK;
943	
944	    FT_TRACE4(( " %d\n", dict->maxstack ));
945	
946	  Exit:
947	    return error;
948	  }
