1558	                  default:  /* for 64-bit systems */
1559	                    *(FT_Long*)q = val;
1560	                  }
1561	
1562	                  FT_TRACE4(( " %ld", val ));
1563	
1564	                  q += field->size;
1565	                  num_args--;
1566	                }
1567	
1568	                FT_TRACE4(( "]\n" ));
1569	              }
1570	              break;
1571	
1572	            default:  /* callback or blend */
1573	              error = field->reader( parser );
1574	              if ( error )
