461	  /* read a floating point number, either integer or real */
462	  static FT_Fixed
463	  do_fixed( CFF_Parser  parser,
464	            FT_Byte**   d,
465	            FT_Long     scaling )
466	  {
467	    if ( **d == 30 )
468	      return cff_parse_real( *d, parser->limit, scaling, NULL );
469	    else
470	    {
471	      FT_Long  val = cff_parse_integer( *d, parser->limit );
472	
473	
474	      if ( scaling )
475	        val *= power_tens[scaling];
476	
477	      if ( val > 0x7FFF )
478	      {
479	        val = 0x7FFFFFFFL;
480	        goto Overflow;
481	      }
482	      else if ( val < -0x7FFF )
483	      {
484	        val = -0x7FFFFFFFL;
485	        goto Overflow;
486	      }
487	
488	      return (FT_Long)( (FT_ULong)val << 16 );
489	
490	    Overflow:
491	      FT_TRACE4(( "!!!OVERFLOW:!!!" ));
492	      return val;
493	    }
494	  }
495	
496	
497	  /* read a floating point number, either integer or real */
498	  static FT_Fixed
499	  cff_parse_fixed( CFF_Parser  parser,
500	                   FT_Byte**   d )
501	  {
502	    return do_fixed( parser, d, 0 );
503	  }
