682	  static FT_Error
683	  cff_parse_font_bbox( CFF_Parser  parser )
684	  {
685	    CFF_FontRecDict  dict = (CFF_FontRecDict)parser->object;
686	    FT_BBox*         bbox = &dict->font_bbox;
687	    FT_Byte**        data = parser->stack;
688	    FT_Error         error;
689	
690	
691	    error = FT_ERR( Stack_Underflow );
692	
693	    if ( parser->top >= parser->stack + 4 )
694	    {
695	      bbox->xMin = FT_RoundFix( cff_parse_fixed( parser, data++ ) );
696	      bbox->yMin = FT_RoundFix( cff_parse_fixed( parser, data++ ) );
697	      bbox->xMax = FT_RoundFix( cff_parse_fixed( parser, data++ ) );
698	      bbox->yMax = FT_RoundFix( cff_parse_fixed( parser, data   ) );
699	      error = FT_Err_Ok;
700	
701	      FT_TRACE4(( " [%d %d %d %d]\n",
702	                  bbox->xMin / 65536,
703	                  bbox->yMin / 65536,
704	                  bbox->xMax / 65536,
705	                  bbox->yMax / 65536 ));
706	    }
707	
708	    return error;
709	  }
