874	  static FT_Error
875	  cff_parse_blend( CFF_Parser  parser )
876	  {
877	    /* blend operator can only be used in a Private DICT */
878	    CFF_Private  priv = (CFF_Private)parser->object;
879	    CFF_SubFont  subFont;
880	    CFF_Blend    blend;
881	    FT_UInt      numBlends;
882	    FT_Error     error;
883	
884	
885	    error = FT_ERR( Stack_Underflow );
886	
887	    if ( !priv || !priv->subfont )
888	    {
889	      error = FT_THROW( Invalid_File_Format );
890	      goto Exit;
891	    }
892	
893	    subFont = priv->subfont;
894	    blend   = &subFont->blend;
895	
896	    if ( cff_blend_check_vector( blend,
897	                                 priv->vsindex,
898	                                 subFont->lenNDV,
899	                                 subFont->NDV ) )
900	    {
901	      error = cff_blend_build_vector( blend,
902	                                      priv->vsindex,
903	                                      subFont->lenNDV,
904	                                      subFont->NDV );
905	      if ( error != FT_Err_Ok )
906	        goto Exit;
907	    }
908	
909	    numBlends = (FT_UInt)cff_parse_num( parser, parser->top - 1 );
910	
911	    FT_TRACE4(( "   %d values blended\n", numBlends ));
912	
913	    error = cff_blend_doBlend( subFont, parser, numBlends );
914	
915	    blend->usedBV = TRUE;
916	
917	  Exit:
918	    return error;
919	  }
