937	
938	    dict->maxstack = (FT_UInt)cff_parse_num( parser, data++ );
939	    if ( dict->maxstack > CFF2_MAX_STACK )
940	      dict->maxstack = CFF2_MAX_STACK;
941	    if ( dict->maxstack < CFF2_DEFAULT_STACK )
