1231	  FT_LOCAL_DEF( FT_Error )
1232	  cff_parser_run( CFF_Parser  parser,
1233	                  FT_Byte*    start,
1234	                  FT_Byte*    limit )
1235	  {
1236	    FT_Byte*    p       = start;
1237	    FT_Error    error   = FT_Err_Ok;
1238	    FT_Library  library = parser->library;
1239	    FT_UNUSED( library );
1240	
1241	
1242	    parser->top    = parser->stack;
1243	    parser->start  = start;
1244	    parser->limit  = limit;
1245	    parser->cursor = start;
1246	
1247	    while ( p < limit )
1248	    {
1249	      FT_UInt  v = *p;
1250	
1251	      /* Opcode 31 is legacy MM T2 operator, not a number.      */
1252	      /* Opcode 255 is reserved and should not appear in fonts; */
1253	      /* it is used internally for CFF2 blends.                 */
1254	      if ( v >= 27 && v != 31 && v != 255 )
1255	      {
1256	        /* it's a number; we will push its position on the stack */
1257	        if ( (FT_UInt)( parser->top - parser->stack ) >= parser->stackSize )
1258	          goto Stack_Overflow;
1259	
1260	        *parser->top++ = p;
1261	
1262	        /* now, skip it */
1263	        if ( v == 30 )
1264	        {
1265	          /* skip real number */
1266	          p++;
1267	          for (;;)
1268	          {
1269	            /* An unterminated floating point number at the */
1270	            /* end of a dictionary is invalid but harmless. */
1271	            if ( p >= limit )
1272	              goto Exit;
1273	            v = p[0] >> 4;
1274	            if ( v == 15 )
1275	              break;
1276	            v = p[0] & 0xF;
1277	            if ( v == 15 )
1278	              break;
1279	            p++;
1280	          }
1281	        }
1282	        else if ( v == 28 )
1283	          p += 2;
1284	        else if ( v == 29 )
1285	          p += 4;
1286	        else if ( v > 246 )
1287	          p += 1;
1288	      }
1289	#ifdef CFF_CONFIG_OPTION_OLD_ENGINE
1290	      else if ( v == 31 )
1291	      {
1292	        /* a Type 2 charstring */
1293	
1294	        CFF_Decoder  decoder;
1295	        CFF_FontRec  cff_rec;
1296	        FT_Byte*     charstring_base;
1297	        FT_ULong     charstring_len;
1298	
1299	        FT_Fixed*  stack;
1300	        FT_Byte*   q;
1301	
1302	
1303	        charstring_base = ++p;
1304	
1305	        /* search `endchar' operator */
1306	        for (;;)
1307	        {
1308	          if ( p >= limit )
1309	            goto Exit;
1310	          if ( *p == 14 )
1311	            break;
1312	          p++;
1313	        }
1314	
1315	        charstring_len = (FT_ULong)( p - charstring_base ) + 1;
1316	
1317	        /* construct CFF_Decoder object */
1318	        FT_ZERO( &decoder );
1319	        FT_ZERO( &cff_rec );
1320	
1321	        cff_rec.top_font.font_dict.num_designs = parser->num_designs;
1322	        cff_rec.top_font.font_dict.num_axes    = parser->num_axes;
1323	        decoder.cff                            = &cff_rec;
1324	
1325	        error = cff_decoder_parse_charstrings( &decoder,
1326	                                               charstring_base,
1327	                                               charstring_len,
1328	                                               1 );
1329	
1330	        /* Now copy the stack data in the temporary decoder object,    */
1331	        /* converting it back to charstring number representations     */
1332	        /* (this is ugly, I know).                                     */
1333	        /*                                                             */
1334	        /* We overwrite the original top DICT charstring under the     */
1335	        /* assumption that the charstring representation of the result */
1336	        /* of `cff_decoder_parse_charstrings' is shorter, which should */
1337	        /* be always true.                                             */
1338	
1339	        q     = charstring_base - 1;
1340	        stack = decoder.stack;
1341	
1342	        while ( stack < decoder.top )
1343	        {
1344	          FT_ULong  num;
1345	          FT_Bool   neg;
1346	
1347	
1348	          if ( (FT_UInt)( parser->top - parser->stack ) >= parser->stackSize )
1349	            goto Stack_Overflow;
1350	
1351	          *parser->top++ = q;
1352	
1353	          if ( *stack < 0 )
1354	          {
1355	            num = (FT_ULong)-*stack;
1356	            neg = 1;
1357	          }
1358	          else
1359	          {
1360	            num = (FT_ULong)*stack;
1361	            neg = 0;
1362	          }
1363	
1364	          if ( num & 0xFFFFU )
1365	          {
1366	            if ( neg )
1367	              num = (FT_ULong)-num;
1368	
1369	            *q++ = 255;
1370	            *q++ = ( num & 0xFF000000U ) >> 24;
1371	            *q++ = ( num & 0x00FF0000U ) >> 16;
1372	            *q++ = ( num & 0x0000FF00U ) >>  8;
1373	            *q++ =   num & 0x000000FFU;
1374	          }
1375	          else
1376	          {
1377	            num >>= 16;
1378	
1379	            if ( neg )
1380	            {
1381	              if ( num <= 107 )
1382	                *q++ = (FT_Byte)( 139 - num );
1383	              else if ( num <= 1131 )
1384	              {
1385	                *q++ = (FT_Byte)( ( ( num - 108 ) >> 8 ) + 251 );
1386	                *q++ = (FT_Byte)( ( num - 108 ) & 0xFF );
1387	              }
1388	              else
1389	              {
1390	                num = (FT_ULong)-num;
1391	
1392	                *q++ = 28;
1393	                *q++ = (FT_Byte)( num >> 8 );
1394	                *q++ = (FT_Byte)( num & 0xFF );
1395	              }
1396	            }
1397	            else
1398	            {
1399	              if ( num <= 107 )
1400	                *q++ = (FT_Byte)( num + 139 );
1401	              else if ( num <= 1131 )
1402	              {
1403	                *q++ = (FT_Byte)( ( ( num - 108 ) >> 8 ) + 247 );
1404	                *q++ = (FT_Byte)( ( num - 108 ) & 0xFF );
1405	              }
1406	              else
1407	              {
1408	                *q++ = 28;
1409	                *q++ = (FT_Byte)( num >> 8 );
1410	                *q++ = (FT_Byte)( num & 0xFF );
1411	              }
1412	            }
1413	          }
1414	
1415	          stack++;
1416	        }
1417	      }
1418	#endif /* CFF_CONFIG_OPTION_OLD_ENGINE */
1419	      else
1420	      {
1421	        /* This is not a number, hence it's an operator.  Compute its code */
1422	        /* and look for it in our current list.                            */
1423	
1424	        FT_UInt                   code;
1425	        FT_UInt                   num_args = (FT_UInt)
1426	                                             ( parser->top - parser->stack );
1427	        const CFF_Field_Handler*  field;
1428	
1429	
1430	        *parser->top = p;
1431	        code = v;
1432	        if ( v == 12 )
1433	        {
1434	          /* two byte operator */
1435	          p++;
1436	          if ( p >= limit )
1437	            goto Syntax_Error;
1438	
1439	          code = 0x100 | p[0];
1440	        }
1441	        code = code | parser->object_code;
1442	
1443	        for ( field = CFF_FIELD_HANDLERS_GET; field->kind; field++ )
1444	        {
1445	          if ( field->code == (FT_Int)code )
1446	          {
1447	            /* we found our field's handler; read it */
1448	            FT_Long   val;
1449	            FT_Byte*  q = (FT_Byte*)parser->object + field->offset;
1450	
1451	
1452	#ifdef FT_DEBUG_LEVEL_TRACE
1453	            FT_TRACE4(( "  %s", field->id ));
1454	#endif
1455	
1456	            /* check that we have enough arguments -- except for */
1457	            /* delta encoded arrays, which can be empty          */
1458	            if ( field->kind != cff_kind_delta && num_args < 1 )
1459	              goto Stack_Underflow;
1460	
1461	            switch ( field->kind )
1462	            {
1463	            case cff_kind_bool:
1464	            case cff_kind_string:
1465	            case cff_kind_num:
1466	              val = cff_parse_num( parser, parser->stack );
1467	              goto Store_Number;
1468	
1469	            case cff_kind_fixed:
1470	              val = cff_parse_fixed( parser, parser->stack );
1471	              goto Store_Number;
1472	
1473	            case cff_kind_fixed_thousand:
1474	              val = cff_parse_fixed_scaled( parser, parser->stack, 3 );
1475	
1476	            Store_Number:
1477	              switch ( field->size )
1478	              {
1479	              case (8 / FT_CHAR_BIT):
1480	                *(FT_Byte*)q = (FT_Byte)val;
1481	                break;
1482	
1483	              case (16 / FT_CHAR_BIT):
1484	                *(FT_Short*)q = (FT_Short)val;
1485	                break;
1486	
1487	              case (32 / FT_CHAR_BIT):
1488	                *(FT_Int32*)q = (FT_Int)val;
1489	                break;
1490	
1491	              default:  /* for 64-bit systems */
1492	                *(FT_Long*)q = val;
1493	              }
1494	
1495	#ifdef FT_DEBUG_LEVEL_TRACE
1496	              switch ( field->kind )
1497	              {
1498	              case cff_kind_bool:
1499	                FT_TRACE4(( " %s\n", val ? "true" : "false" ));
1500	                break;
1501	
1502	              case cff_kind_string:
1503	                FT_TRACE4(( " %ld (SID)\n", val ));
1504	                break;
1505	
1506	              case cff_kind_num:
1507	                FT_TRACE4(( " %ld\n", val ));
1508	                break;
1509	
1510	              case cff_kind_fixed:
1511	                FT_TRACE4(( " %f\n", (double)val / 65536 ));
1512	                break;
1513	
1514	              case cff_kind_fixed_thousand:
1515	                FT_TRACE4(( " %f\n", (double)val / 65536 / 1000 ));
1516	
1517	              default:
1518	                ; /* never reached */
1519	              }
1520	#endif
1521	
1522	              break;
1523	
1524	            case cff_kind_delta:
1525	              {
1526	                FT_Byte*   qcount = (FT_Byte*)parser->object +
1527	                                      field->count_offset;
1528	
1529	                FT_Byte**  data = parser->stack;
1530	
1531	
1532	                if ( num_args > field->array_max )
1533	                  num_args = field->array_max;
1534	
1535	                FT_TRACE4(( " [" ));
1536	
1537	                /* store count */
1538	                *qcount = (FT_Byte)num_args;
1539	
1540	                val = 0;
1541	                while ( num_args > 0 )
1542	                {
1543	                  val += cff_parse_num( parser, data++ );
1544	                  switch ( field->size )
1545	                  {
1546	                  case (8 / FT_CHAR_BIT):
1547	                    *(FT_Byte*)q = (FT_Byte)val;
1548	                    break;
1549	
1550	                  case (16 / FT_CHAR_BIT):
1551	                    *(FT_Short*)q = (FT_Short)val;
1552	                    break;
1553	
1554	                  case (32 / FT_CHAR_BIT):
1555	                    *(FT_Int32*)q = (FT_Int)val;
1556	                    break;
1557	
1558	                  default:  /* for 64-bit systems */
1559	                    *(FT_Long*)q = val;
1560	                  }
1561	
1562	                  FT_TRACE4(( " %ld", val ));
1563	
1564	                  q += field->size;
1565	                  num_args--;
1566	                }
1567	
1568	                FT_TRACE4(( "]\n" ));
1569	              }
1570	              break;
1571	
1572	            default:  /* callback or blend */
1573	              error = field->reader( parser );
1574	              if ( error )
1575	                goto Exit;
1576	            }
1577	            goto Found;
1578	          }
1579	        }
1580	
1581	        /* this is an unknown operator, or it is unsupported; */
1582	        /* we will ignore it for now.                         */
1583	
1584	      Found:
1585	        /* clear stack */
1586	        /* TODO: could clear blend stack here,       */
1587	        /*       but we don't have access to subFont */
1588	        if ( field->kind != cff_kind_blend )
1589	          parser->top = parser->stack;
1590	      }
1591	      p++;
1592	    }
1593	
1594	  Exit:
1595	    return error;
1596	
1597	  Stack_Overflow:
1598	    error = FT_THROW( Invalid_Argument );
1599	    goto Exit;
1600	
1601	  Stack_Underflow:
1602	    error = FT_THROW( Invalid_Argument );
1603	    goto Exit;
1604	
1605	  Syntax_Error:
1606	    error = FT_THROW( Invalid_Argument );
1607	    goto Exit;
1608	  }
1609	
1610	
1611	/* END */
